-- Generated by scripts/pages.ts from i18n/frFR/recipes/: edit those, not this file.
-- pages[chef][spell] = { paragraph, ... }: the chef's page of each dish.
local _, ns = ...
ns.pages = {
  kendor = {
    [2538] = { "Tout cuisinier commence ici, avec un feu, un couteau et un loup qui n'avait aucune envie de finir en dîner. La plupart n'en sortent jamais, et c'est ainsi que les routes de ce royaume se sont mises à sentir le loup brûlé. Griller n'est pas brûler. Vous voulez l'extérieur sombre et croustillant, l'intérieur encore tendre, et cela suppose un feu retombé en braises, pas un feu qui fait encore le fier avec ses flammes. Apprenez cela et vous aurez appris la patience. Ensuite, venez me voir." },
    [2539] = { "Le deuxième plat que tout maître enseigne, et le premier que la plupart des cuisiniers ratent. Ils croient que l'épice est un déguisement. Ils prennent un loup qui s'est usé à courir dans les collines et ils l'ensevelissent, alors que le loup méritait mieux. Frottez l'épice avant que la viande ne rencontre le feu, puis laissez-la reposer. L'épice ajoutée à la fin se pose sur la viande comme un chapeau. Ajoutée au début, elle en fait partie." },
    [2540] = { "Les sangliers d'Elwynn nourrissent cette ville depuis le temps où elle n'avait pas de murs, et ils la nourriront encore quand il faudra les rebâtir une fois de plus. Tomas, à Comté-de-l'Or, les rôtit entiers pour son auberge, tourne la broche à la main et appelle cela la tradition. C'est une belle tradition. C'est aussi pourquoi son sanglier est cuit d'un côté et cru de l'autre. Taillez la viande en morceaux égaux, pour que la chaleur les traite tous de la même façon. En cuisine, la justice est affaire de couteau." },
    [2541] = { "Les coyotes de la Marche de l'Ouest mangent ce que les fermiers ont laissé derrière eux, et leur viande a le goût d'une vie difficile. Vous ne pouvez pas changer son passé. Vous pouvez le respecter. Taillez le steak épais, saisissez-le fort et retirez-le du feu tant que le coeur rosit encore. Un steak de coyote mince et cuit à coeur, c'est une sandale. Un steak épais et reposé, c'est un souper. Chaque apprenti arrive persuadé qu'un steak est une chose simple. C'en est une. C'est bien pour cela qu'il est si facile à rater." },
    [2542] = { "La tourte au foie de Broche-tripes est la fierté des fermes de la Marche de l'Ouest, ou l'était, quand il y avait des fermes dont être fier. Une fermière de la route côtière l'a apprise à la moitié de la province, et je la vends ici avec quelques corrections qu'elle n'est pas encore venue contester à Hurlevent. Le foie d'un Broche-tripes est fort, sombre et riche, et il faut le rincer à l'eau froide avant de le cuire, pour calmer son amertume. Puis des épices douces, et un four qui ne se presse jamais. Un four chaud rend le foie gris et granuleux, avec un goût de fer. Un four lent le laisse tendre et doux, avec le goût de la ferme d'où il vient. La croûte est affaire d'opinion. Le foie ne l'est pas. Quand la tourte sort du four, laissez-la reposer jusqu'à ce qu'elle cesse de chuchoter. Puis coupez-la, et alors seulement la fierté vous sera permise." },
    [2543] = { "Je vends la recette de ce ragoût, ce qui vous dit que je l'approuve, comme on approuve une solide paire de bottes. Les fermiers de la Marche de l'Ouest le faisaient avec ce que la terre leur jetait, le vautour, le groin d'un Broche-tripes, l'oeil de murloc, et ils avaient raison sur les trois. Je l'ai essayé une fois sans l'oeil. Il était maigre, et mon orgueil aussi. C'est l'oeil qui épaissit le bouillon. Laissez mijoter plus longtemps que vous ne le jugez nécessaire, puis plus longtemps encore. Un ragoût bâclé n'est qu'une soupe qui a menti. Aujourd'hui, les fermes sont vides, et ce ragoût est cuisiné par ceux qui les ont perdues, dans les camps qui bordent la route de la Colline des sentinelles. Il n'a rien de raffiné. Il est honnête, et dans la Marche de l'Ouest, c'est devenu plus rare que le raffinement." },
    [2544] = { "Tous les maîtres enseignent les beignets de crabe, et tous les enseignent trop humides. De la chair de clampant bien nettoyée, une pincée d'épices douces, le tout pressé à la main et rien d'autre, puis frit jusqu'à ce que l'extérieur prenne en une croûte qui tient le reste. S'il s'effondre, vous n'avez pas assez pressé. S'il rebondit, vous avez trop pressé. Un beignet de crabe doit être ferme comme une poignée de main est ferme, et pas davantage." },
    [2545] = { "La côte de la Marche de l'Ouest grouille de crabes, et les contrebandiers défias qui s'y cachent m'ont volé ma recette pour leurs pinces. J'en suis flatté. Une pince va au feu fendue, sinon la chair cuit à la vapeur dans sa propre armure et en sort cotonneuse. Poussez les épices douces dans la fente avec le pouce et donnez-lui un feu bref et chaud. Puis tirez la chair à la fourchette, et rappelez-vous que même les voleurs mangent bien quand ils volent le bon cuisinier." },
    [2546] = { "Les côtes sèches sont un plat de fermier, des côtes de sanglier et une croûte d'épices, sans la moindre sauce. Certains cuisiniers en ont peur. Ils croient qu'une côte doit dégouliner pour être bonne. Une côte doit être cuite pour être bonne. Frottez l'épice la veille, laissez le feu retomber jusqu'à une lueur sourde et donnez aux côtes l'après-midi entier. Elles en sortent sombres, croustillantes et sèches au toucher, et ne laissent rien sur l'os." },
    [2547] = { "Le goulash des Carmines, c'est de l'araignée et du condor, mijotés ensemble par les gens de Comté-du-Lac, qui ont des araignées et des condors à revendre depuis que les gnolls ont pris le reste. Les deux viandes cuisent à des vitesses très différentes, et tout l'art est dans le minutage. Le condor demande presque tout l'après-midi pour s'attendrir. L'araignée n'en demande qu'une fraction, et devient filandreuse si elle reste davantage. Ajoutez-la tard. Je vends la recette avec cet avertissement écrit dans la marge, de ma main." },
    [2548] = { "Les gnolls des Carmines transportent cette recette dans leurs sacs, volée dans quelque ferme, et n'en font rien. Je vends la même à Hurlevent et j'en fais beaucoup. Des côtes de sanglier et des épices fortes, et tout le secret tient au retournement. Retournez-les souvent, et la graisse qui fond arrose la viande en descendant. Le nom ne promet rien. Le moelleux est la récompense de l'attention." },
    [2549] = { "Voilà le plat auquel je mettrais mon nom, et je l'ai fait. Du steak de loup et des herbes aromatiques de Stormwind, rien d'autre, et quiconque vous propose de quoi remplacer les herbes a quelque chose à vous vendre. Laissez un espace entre les morceaux sur la brochette, pour que le feu atteigne chaque face de la viande. Laissez-la reposer avant de manger. Une brochette arrachée trop tôt au feu pleure dans l'assiette, et vous pleurerez avec elle." },
    [2795] = { "Ragnar Thunderbrew croit que cette recette appartient à sa famille. Je la vends à Hurlevent à un prix honnête, et je l'ai améliorée. Il vous dira que les côtes veulent la bière au malt Rhapsody de la première minute à la dernière. C'est faux. Les nains arrosent dès le départ, puis s'étonnent que le dehors brûle pendant que le dedans boude. Rôtissez la côte sans rien dessus jusqu'à ce que la graisse coule claire. Alors, et pas une minute plus tôt, passez la bière au pinceau en couches fines, chacune sèche avant la suivante, pour bâtir un glaçage et non du charbon. Le résultat est sucré, sombre et collant, et c'est ce que Dun Morogh a produit de plus beau. Je le dirais à Ragnar, s'il entendait quoi que ce soit par-dessus sa propre taverne. Il le sait. Ses côtes se sont améliorées depuis." },
    [3370] = { "Le crocilisque est le steak de ceux qui trouvent le boeuf trop complaisant. Les Paluns en regorgent, et les chasseurs de Menethil m'apportent les queues dans des tonneaux de saumure. Malgré toutes ces dents, la queue se mange comme un poisson, blanche et serrée, et elle se cuit comme un poisson épais : une chaleur féroce, brève, et une seule fois. Le crocilisque réchauffé le lendemain est une punition que je réserve aux élèves qui l'ont laissé traîner." },
    [3371] = { "Les nains de Thelsamar font le boudin chaque hiver et en envoient quelques-uns à Forgefer, où Daryl Riknussun les vante bruyamment avant d'apprendre à ses élèves à les faire moins bien. Je vends ici la recette, corrigée. De la viande d'ours, des tripes de sanglier nettoyées et de l'ichor d'araignée, qui lie comme le sang le faisait et se conserve bien mieux. Remplissez le boyau sans trop serrer. Un boudin trop serré éclate dans la poêle et se vide sur les braises, et personne n'a jamais aimé un boudin qui abandonne." },
    [3372] = { "Les ailerons de murloc donnent une soupe qui a plus de corps que vous ne le croiriez, si vous n'avez croisé les murlocs qu'au bout d'une épée. Faites mijoter les ailerons avec des épices fortes jusqu'à ce qu'ils fondent dans le bouillon et lui donnent une richesse digne du meilleur fond d'os. Les murlocs protesteraient, si on leur demandait leur avis. Les murlocs protestent contre tout, longuement, et jamais dans une langue que je tienne à apprendre." },
    [3373] = { "Le gombo est un plat des marais, un ragoût épais et sombre que les gens des Paluns cuisinent comme si leur vie en dépendait, ce qui, aux Paluns, arrive parfois. La viande de crocilisque tendre et les épices fortes vont dans la marmite et réduisent lentement, jusqu'à ce que le gombo nappe une cuillère et y reste. La couleur est la mesure. Trop pâle, on l'a pressé. Trop sombre, vous avez brûlé le fond de la marmite et devriez recommencer avec dignité." },
    [3376] = { "Au goût étrange, c'est le nom le plus honnête de mon catalogue, car tous ceux qui la mangent s'étonnent qu'elle soit si bonne. C'est un oeuf de raptor, bien plus riche que celui d'une poule, et des épices fortes. Un fouet vigoureux, une poêle rapide, un pliage doux. L'oeuf de raptor prend lentement au centre, et le cuisinier qui se presse sert un centre cru. L'étonnement est mérité. L'omelette est la mienne, par droit d'amélioration." },
    [3377] = { "Je vends une recette appelée tourte d'araignée fondante, et je la vends sans sourire, parce qu'elle est très bonne. Des pattes d'araignée fondantes, dont on tire la chair, mêlée d'épices fortes, pressée en galettes et frite jusqu'à porter une croûte digne de ce nom et un coeur encore tendre. Le fondant est dans le nom et doit rester au milieu. Une galette qui coule a été frite trop chaud. Les gens du Bois de la Pénombre en mangent à la douzaine, ce qui est la chose la plus courageuse que je sache du Bois de la Pénombre." },
    [3397] = { "Les ours d'Orneval deviennent plus grands que les nôtres, nourris de la patience des elfes de la nuit et de ce qu'ils trouvent sous les arbres. Leur viande est sombre et riche, et réclame une épice forte pour en trancher la richesse. Saisissez-la fort et laissez-la reposer plus longtemps que la décence ne semble le permettre, plus longtemps qu'une bête plus petite, car un gros steak continue de cuire une fois sorti du feu. En Désolace, une machine gobeline vend mes recettes un exemplaire à la fois. J'aimerais rencontrer son cuisinier." },
    [3398] = { "Des lions des Tarides, coupés en côtelettes et brûlés aux épices fortes par des cuisiniers qui appellent le résultat un mets de choix. J'appelle cela un lion qui méritait mieux. La viande la plus douce du lion se tient contre l'os, alors la côtelette cuit sur l'os, et celui qui la désosse d'abord mérite ce qu'il obtient. L'épice forte est la bienvenue. Le feu fort ne l'est pas. Donnez aux côtelettes une chaleur modérée et retournez-les souvent. Un lion doit arriver à table avec l'air d'avoir perdu un combat loyal." },
    [3399] = { "Délicieux, dit-il de lui-même, et c'est bien trop modeste. Du lion et des épices apaisantes, laissé entier en steak, la seule manière civilisée de manger un lion. L'épice apaisante n'est pas là pour calmer le cuisinier. Elle arrondit la douceur de la viande. Saisissez, laissez reposer, et tranchez en travers des fibres. Un steak de lion tranché dans le sens du fil se mâche comme une dispute impossible à gagner, et j'ai vu des élèves s'y essayer." },
    [3400] = { "Une bisque est une soupe lisse, et la bisque de tortue est lisse parce que la tortue a abandonné tout ce qu'elle avait à donner. La viande de tortue et les épices apaisantes mijotent tout l'après-midi, puis la marmite entière passe au tamis fin. Pressez avec le dos d'une louche jusqu'à ce qu'il ne reste rien où une cuillère puisse accrocher. Sautez cette étape et vous aurez une soupe de tortue, ce qui est une chose différente et moindre. Apaisante, dit-elle d'elle-même. Je dirais patiente, et j'aurais raison." },
    [4094] = { "Dans les Terres ingrates, on vous dira qu'un busard ne vaut pas les braises. Ceux qui le disent ne l'ont jamais mangé grillé. Une aile de busard n'est que tendon et rancune, alors elle veut des épices fortes et des heures de chaleur douce, puis, tout à la fin seulement, une flambée féroce pour la peau. Les chasseurs d'Arathi vendent la recette pour une bouchée de pain, ce qui est un crime contre la cuisine, et je ne l'ai signalé à personne." },
    [6412] = { "Les elfes de la nuit de Teldrassil vous enseigneront ce kébab pour le prix de quelques pattes d'araignée, ce qui vous dit ce qu'ils pensent des araignées. Alegorn, à Darnassus, voudrait que vous enfiliez chaque patte avec un brin de verdure et que vous disposiez les brochettes comme un poème. Oubliez le poème. Les pattes d'araignée veulent une chaleur vive et brève, juste de quoi fendre la carapace, sinon la chair se change en ficelle. Ensuite, garnissez si vous y tenez. Je n'y tiens jamais." },
    [6413] = { "Un plat de la Horde, venu de la poussière de Durotar, et la surprise, c'est que quelqu'un mange un scorpide exprès. La cuisine d'Orgrimmar n'est pas une chose que j'aie besoin de goûter. J'en ai pourtant lu la recette, car un maître lit tout. Sa seule sagesse est le dard, qu'il faut cuire jusqu'à ce qu'il casse net de part en part. Alors le venin est parti et il ne reste que le mordant. Trop peu cuit, il garde les deux. Je vous laisse décider lequel des deux vous appelleriez une surprise." },
    [6414] = { "Le kodo est la viande de Mulgore, rôtie là-bas par des taurens qui cuisinent à ciel ouvert, avec la plaine pour cuisine. Je ne me suis jamais tenu sous ce ciel, et je n'en ai pas l'intention. Le kodo est un animal énorme et patient, et sa viande l'est aussi : dure d'abord, généreuse à la fin. Rôtissez-la lentement et accordez-lui un long repos avant le couteau. Les taurens ont raison sur un point, et le voici : certaines viandes ne se laissent presser par personne." },
    [6415] = { "Les furies de Sombrivage ne sont que dents et mauvaises manières, et les elfes de la nuit les lèvent en filets avec une révérence que je trouve excessive. Alegorn voudrait que vous posiez le filet sur une feuille et que vous murmuriez au-dessus. Je voudrais que vous l'assaisonniez légèrement et le cuisiez vite, car la chair de furie est molle et se défait pour peu qu'on la regarde lentement. Une poêle chaude, la peau d'abord, et un seul retournement quand la chair blanchit au bord. La feuille est facultative. Le murmure ne me regarde pas." },
    [6416] = { "Le trotteur est l'oiseau aux longues pattes des Tarides, tout en cou et en opinions, et la Horde le fait mijoter avec des pommes, ce qui est la première chose sensée que j'aie entendu dire d'eux. La pomme adoucit le bouillon et attendrit la viande, et la viande en a besoin. Laissez mijoter lentement jusqu'à ce que la pomme ait disparu et que l'oiseau ait renoncé à son entêtement. Je ne traverserais pas la mer pour lui." },
    [6417] = { "Un brouet de rats, enseigné par la Horde dans les Tarides à quiconque veut bien leur attraper les rats. Je l'inclus parce que je suis consciencieux, non parce que je le recommande. Un rat fouisseur est petit, maigre et plus propre que les rats de nos égouts, ce qui est un maigre éloge. Faites-le mijoter longtemps. Tout dans ce plat appelle une longue cuisson, y compris le besoin qu'a le cuisinier d'oublier ce qu'il y a dans la marmite." },
    [6418] = { "Un plat des Tarides, vendu à la Croisée et mangé par la Horde avec les doigts. Je ne mentionne les doigts que pour que vous ne les imitiez pas. Une queue de lézard-tonnerre n'est que muscle, et le croquant vient de la cuisson dans sa propre graisse, jusqu'à ce que la peau vole en éclats. Des épices fortes, une poêle brûlante, et un cuisinier assez courageux pour l'y laisser. Je ne prétendrai pas admirer les Tarides. Mangée au couteau et à la fourchette, la queue est presque civilisée." },
    [6419] = { "La venaison est la viande d'un cuisinier bien élevé. Un cerf est maigre et fier, et il se traite comme tel, avec beaucoup d'épices bien frottées et très peu de temps sur le feu. Faites trop cuire un cerf et vous insultez la forêt. Les elfes d'Orneval vendent cette recette, ce que je trouve curieux, eux qui passent une si grande part de leur vie à empêcher quiconque de chasser leurs cerfs. Servez-la saignante, tranchez-la fin, et taisez sa provenance." },
    [6499] = { "Une palourde, c'est une bouchée de mer, et la seule façon de la gâcher est de l'oublier dans la marmite, ce que tout le monde fait. Les marins du port les font bouillir dans l'eau de mer et appellent cela une tradition. J'appelle cela de la paresse avec vue sur le large. Prenez une bonne eau de source, et sortez la chair dès qu'elle se raffermit et blanchit. Le caoutchouc, c'est pour les bottes. Si vous éprouvez le besoin d'une sauce, c'est que vous les avez trop cuites." },
    [6500] = { "Les gobelins préparent leurs palourdes comme ils font des affaires : avec trop de chaleur et trop de bruit. J'enseigne la recette malgré tout, et je corrige la chaleur. De la chair de palourde relevée, des épices fortes, et un feu près duquel vous pouvez tenir la main un instant sans regret. Une palourde sur un feu furieux se réduit à un bouton, et un bouton se mâche. Une palourde bien cuite garde juste assez de combat pour vous rappeler qu'elle vient de la mer. Les gobelins vous feraient payer le bouton deux fois plus cher." },
    [6501] = { "Une soupe de palourdes, ce sont des palourdes et du lait, et le lait ne doit jamais bouillir. C'est toute la difficulté, et elle suffit à vaincre la plupart des cuisiniers de la côte. La chair de palourde entre avec un peu d'épices douces une fois le lait tiède, et dès lors la marmite reste sous le frémissement jusqu'au bol. Le lait bouilli tranche, et une soupe tranchée ressemble à une erreur dans un bol. Les poissonnières de la Marche de l'Ouest la réussissent plus souvent que les auberges. Les auberges devraient avoir honte." },
    [7213] = { "Les cuisiniers de Baie-du-Butin saisissent une palourde géante dans les épices fortes et la servent aux pirates, qui mangeraient n'importe quoi qui ne mord pas, et plusieurs choses qui mordent. Je l'ai affinée. La chair de palourde géante est dense et douce, et l'astuce est le couteau : tranchez-la si fin que la lame se voit au travers, et l'épice atteindra le centre. Puis un feu féroce, et pas longtemps. Une ardeur doit roussir les sourcils du cuisinier et épargner la palourde." },
    [7751] = { "Le premier poisson de tout enfant muni d'une canne, et le premier poisson que bien des cuisiniers ne dépassent jamais. Un goujon, c'est une bouchée, et une bouchée ne pardonne rien. Cuisez-le entier, dans une poêle chaude, et seulement jusqu'à ce que l'oeil se trouble. C'est votre horloge, et le poisson la porte pour vous. Les pêcheurs du port les vendent au seau aux enfants, qui les brûlent. Je ne les vends pas. Je les corrige." },
    [7752] = { "Le maquereau est un poisson gras, et la graisse est un cadeau que la plupart des cuisiniers traitent comme un problème. Ils la noient, ils la grattent, ils s'en excusent. Posez-le côté peau dans une poêle sèche et brûlante, et laissez sa propre graisse faire la cuisine. La peau croustille, la chair reste douce, et la cuisine sent la mer pendant une journée, ce qui n'a rien d'une punition. J'ai appris cela sur les quais, enfant. Je ne l'ai amélioré que légèrement, ce qui, venant de moi, est un compliment." },
    [7753] = { "Un lutjan des fonds vaseux des rivières lentes, et il en a le goût, à moins de savoir mieux faire. Je sais mieux faire. Nettoyez-le bien et cuisez-le entier, avec sa peau, sur un feu modéré, puis retirez la peau avant de servir, et la vase s'en va avec elle. Les pêcheurs le mangent avec la peau et tout, et vous disent que la rivière fait partie du charme. La rivière a sa place dans la rivière, non dans l'assiette." },
    [7754] = { "Les nains du Loch Modan ont appelé ce plat un délice, le mot le plus généreux que j'aie jamais entendu un nain employer pour une chose sans malt dedans. La furie du loch est plus ferme que ses cousines du sud, une chair d'eau froide qui se tient dans la poêle. Assaisonnez-la d'épices douces, cuisez-la vite et servez-la chaude. Le nom peut rester. La méthode des nains, qui consiste surtout à crier, ne le peut pas." },
    [7755] = { "Le poisson-chat est un poisson de rivière, à large gueule et à moustaches, et généralement méprisé par ceux qui ne l'ont jamais cuisiné comme il faut. Leur erreur est la peau. Elle garde toutes les saveurs du lit de la rivière, et personne ne m'a jamais demandé un lit de rivière. Ôtez-la avant que la poêle voie le poisson, et ce qui reste est doux, sucré et assez ferme pour frire à vif sans se défaire. Les pêcheurs des rivières de Hautebrande ne jurent que par lui, puis le font frire entier, ce qui explique leur réputation de cuisiniers." },
    [7827] = { "Le thon est un poisson pour ceux qui pensent qu'un poisson devrait se conduire comme une viande, et pour une fois le poisson est d'accord. Sa chair est ferme, sombre et riche, alors saisissez-la fort et arrêtez bien avant que le coeur soit cuit. Les marins de Menethil le cuisent jusqu'à ce qu'il soit gris d'un bord à l'autre, puis accusent le poisson. Je ne vends aucune recette pour lui, mais je le ferais, et plus cher. Le thon d'un marin est une ration. Le mien est un repas." },
    [7828] = { "La morue est le poisson des mers froides et des cuisines honnêtes, et la morue rochécaille est la meilleure de toutes, ainsi nommée parce que ses écailles sont dures comme l'ardoise. Écaillez-la avant toute autre chose, avec une bonne lame et de la patience. Séchez-la, couchez-la dans une poêle chaude et retournez-la une fois, quand le bord blanchit. La chair est blanche et se défait en grandes lamelles nettes, et elle n'a besoin de rien, pas même d'un avis, ce qu'il est bien difficile de refuser à une morue." },
    [8238] = { "Les poissons déviants vivent dans les bassins empoisonnés des Cavernes des lamentations, dans les Tarides, et je n'ai jamais eu le moindre désir d'aller en chercher un. La recette se trouve dans le ventre des kodos qui errent là-bas, ce qui vous dit ce que les kodos en pensent. Cuisez-le à coeur, avec des épices douces, et mangez-le à vos risques. Ses effets sur ceux qui le mangent sont, de l'avis de tous, singuliers. On me dit beaucoup de choses sur les Tarides." },
    [8604] = { "Dans cette ville, tous les cuisiniers se croient capables de cuire un oeuf. La plupart se trompent, et toujours de la même façon : trop chaud, trop longtemps, et pressés d'en finir. C'est le premier plat que j'enseigne, et celui sur lequel je juge un cuisinier. Assaisonnez le blanc, jamais le jaune. Le jaune est déjà parfait et se passe très bien de votre avis. Tomas, à Comté-de-l’Or, en réussit de fort honorables. C'est moi qui le lui ai appris." },
    [8607] = { "Le fumage est l'art des nains, et je le dis sans plaisir. Au Loch Modan, ils pendent la viande d'ours dans la fumée de leurs cheminées et l'y oublient tout l'hiver, et au printemps elle vaut mieux que tout ce qu'ils comptaient cuisiner. Le secret, c'est la distance. La viande pend haut, hors de portée de la chaleur, pour que seule la fumée fasse le travail. Près du feu, vous rôtissez mal. Loin du feu, vous fumez bien." },
    [9513] = { "Le thé de chardon est la boisson des voleurs de ce royaume, qui l'infusent avec du chardonnier et de l'eau de source avant d'aller faire ce que font les voleurs. Je ne demande rien. L'eau doit avoir cessé de bouillir un souffle avant de rencontrer la feuille, et la feuille doit quitter la tasse dès que vient la couleur, un vert teinté d'or. Laissée plus longtemps, elle devient âpre. Les voleurs le boivent âpre. Je préfère savoir où se trouve ma bourse pendant qu'ils le boivent." },
    [13028] = { "La dorépine pousse dans les endroits durs, Strangleronce et les Hinterlands, et elle donne un thé que tout maître enseigne et que tout soldat emporte. Elle est forte, et c'est une erreur de l'insulter avec une bouilloire furieuse. Laissez la bouilloire se reposer un instant, versez, et retirez la dorépine quand la tasse prend l'ambre d'une bonne lampe. Une dorépine oubliée dans la tasse rend le thé assez amer pour décaper une peinture. Je l'ai vu faire. La peinture ne s'en est pas remise." },
    [15853] = { "Un steak tout simple, pris au flanc d'un loup, et la simplicité est la chose la plus difficile à cuisiner. Pas de sauce derrière laquelle se cacher, pas de ragoût pour y enterrer une erreur. Le flanc est maigre : il faut le saisir vite et le laisser reposer longtemps, avec un peu d'épices pour lui rappeler qu'il est un aliment. Saignant, c'est correct. Un peu plus cuit, c'est pardonnable. Au-delà, je vous suggère un autre métier, et j'en connais plusieurs qui se passent de feu." },
    [15855] = { "Le rôti de raptor est une nourriture de soldats, vendue dans les camps de Strangleronce, où les hommes mangent ce qui a voulu les manger. C'est une raison suffisante pour le respecter. La chair de raptor est maigre et vive, alors elle rôtit mieux en gros morceaux qui protègent leur propre coeur. Épicez fort le dehors, saisissez sur un feu vigoureux, puis écartez-la de la chaleur pour finir. Un raptor rôti comme un poulet en sort comme une botte. Un raptor rôti comme un raptor en sort comme une victoire." },
    [15856] = { "Les loups du grand sud sont rouges, mal lunés et plus grands que les nôtres, et leurs côtes sont bien garnies. Feralas vend cette recette à quiconque passe par là, ce qui arrive rarement. Des épices fortes, un feu vif, puis de la patience, car le loup rouge est plus gras que notre loup gris et demande du temps pour fondre. Quand la graisse coule claire et que les os brunissent, c'est prêt. Quand la graisse fume, votre réputation aussi." },
    [15861] = { "Un ragoût de Strangleronce, fait par des soldats qui avaient de la viande de tigre, de l'eau de source et des pommes, et l'esprit de les réunir. Les pommes adoucissent ce qui serait sinon un bouillon dur et sauvage. Faites d'abord dorer le tigre bien fort, car un ragoût commencé pâle reste pâle. L'eau et les pommes suivent, et le tout mijote jusqu'à ce que le fruit ait disparu. Une jungle produit beaucoup de nourriture et très peu de recettes. Celle-ci est l'une des bonnes." },
    [15863] = { "Tourte surprise. J'ai relu la recette deux fois, au cas où ce serait une plaisanterie. Ce n'en est pas une. De la viande mystère et des épices fortes, cuites en un plat que les trolls du Marais des Chagrins vendent comme s'il s'agissait d'une gentillesse. La viande doit être cuite à coeur, puis cuite à coeur de nouveau, car quoi qu'elle ait été, elle est morte depuis un moment. Je ne sers pas ce plat. Je l'enseigne, pour que mes élèves sachent ce qu'ils évitent." },
    [15865] = { "Le ragoût mystère, c'est de la viande mystère mijotée dans de la bière naine, et le mystère est de savoir laquelle des deux fait le plus de travail. Je vais vous le dire : la bière. Une bonne bière naine brunit la viande, la détend et laisse au bouillon une amertume qui couvre une multitude de péchés. Daryl Riknussun l'enseigne à Forgefer comme un plat nain, ce qui est généreux de sa part, puisque les nains n'ont fourni que la bière et les questions. Faites-le cuire longtemps. Quoi que la viande ait été, elle doit l'oublier. Écumez à mesure que l'écume monte. Un bouillon qui bout aigrit la bière et change la viande en ficelle. Servi à Theramore et en Désolace à des gens qui ont cessé de poser des questions, il est, je l'avoue, très bon. J'ai cessé de poser des questions moi aussi. C'était plus facile que je ne le pensais." },
    [15906] = { "Ce plat est né d'un pari, dans une taverne où personne n'avoue avoir bu. Il a dépassé ses origines, comme moi. La plupart des cuisiniers en font un concours et le cuisinent comme une arme, ce qui en dit plus long sur eux que sur le chili. La viande mystère est un nom, non une excuse. Parez-la comme si elle avait une réputation à perdre. Faites griller les épices avant que rien d'autre ne les touche, pour les réveiller. Le petit sac de flammes entre en dernier, percé une seule fois, et vous reculez bien. Vous comprendrez pourquoi le jour où vous vous tromperez. Bien fait, le feu arrive tard et repart lentement, comme un bon invité. Mal fait, il arrive le premier et reste toute la soirée, et les Veilleurs peuvent bien le garder." },
    [15910] = { "Les kodos de Désolace deviennent plus grands que tous ceux des Tarides en ne mangeant rien du tout, et leur viande est plus dense que toutes celles que je vends. Je n'ai nul besoin de goûter la cuisine de la Horde, et je fais une exception pour ce ragoût, parce qu'il tient moins de la Horde que du kodo, et le kodo n'y est pour rien. Des épices apaisantes, de l'eau de source, et la patience d'une journée, sur un feu si bas qu'il compte à peine pour un feu. La viande entre froide et ressort en fils. Ne la pressez pas, et ne soulevez pas le couvercle toutes les heures pour voir comment elle va. Elle fait ce que fait le kodo : elle prend son temps. En Désolace, on vend cette recette en vue des ossements de kodos qui jonchent la vallée, ce qui me semble un peu indélicat, et parfaitement pratique." },
    [15915] = { "Le crabe au chili est un plat du sud brûlant, où les cuisiniers tiennent l'épice pour une forme d'hospitalité. De la viande de crabe tendre, plus d'épices fortes que la sagesse ne le conseille, et une poêle si chaude que la cuisine en tousse. Le crabe doit cuire dans l'épice, non dessous, alors remuez sans cesse. C'est salissant à manger, et impossible à manger poliment. Je le sers avec un avertissement et une grande serviette, et je garde la serviette." },
    [15933] = { "Une omelette monstrueuse se fait avec un oeuf géant, et un oeuf géant suffit à nourrir une table de six, ou un orc. Les oeufs géants sont le commerce du grand nord, et la recette se vend en Gangrebois et au Berceau-de-l'Hiver, chez des marchands qui gardent leurs fournisseurs pour eux. Battez l'oeuf avec les épices apaisantes plus longtemps que votre bras ne le souhaite. Puis posez la plus large poêle que vous possédiez sur un feu modéré, et ramenez à la fourchette les bords pris vers le centre. La tentation est de la presser, parce qu'elle est grande et que les invités regardent. Résistez. Une omelette monstrueuse cuite vite est brune dehors et crue dedans, et personne ne le pardonne. Pliez-la quand le dessus a tout juste pris et laissez la chaleur finir le coeur sur le chemin de la table. Puis portez-la à deux mains, et savourez le silence." },
    [15935] = { "Cette recette vient de Tirisfal, où les cuisiniers sont morts et les chauves-souris pas encore. Elle m'est parvenue par un marchand en qui j'ai plus confiance qu'en sa marchandise. Je lui accorde ceci : une aile, c'est surtout de la peau, et la peau récompense le cuisinier qui sait la laisser tranquille. Séchez-la, pressez-la à plat dans une poêle de fer bien chaude, et tenez bon jusqu'à ce qu'elle se décolle d'elle-même. Tout l'art est là. Le reste de la cuisine de Tirisfal, je le laisse à Tirisfal." },
    [18238] = { "Un jaune-queue des hauts-fonds de Tanaris, vendu par un gobelin qui pèse son poisson d'une main et le client de l'autre. Le poisson est excellent malgré tout. Il est ferme et gras, et ne demande qu'une poêle chaude et un seul retournement. Ne le tracassez pas, quoi qu'en veuillent vos mains. Le jaune-queue tacheté est ce poisson rare qui gagne à ce que le cuisinier en fasse moins, et bien des cuisiniers trouvent cela insupportable." },
    [18239] = { "Un gros poisson luisant des mers du sud, et un poisson riche, taillé en tranches épaisses. Un poisson riche donne envie au cuisinier de le combattre à l'épice forte. N'en faites rien. L'épice apaisante est la bonne partenaire, parce qu'elle s'accorde avec le poisson au lieu de lui tenir tête. Saisissez les tranches bien brunes et laissez-les se poser hors du feu. Les marins de Baie-du-Butin le cuisent en grosses pièces sur du bois flotté et le mangent au couteau. Je l'ai vu, et je préfère ne pas le décrire." },
    [18240] = { "Le calmar a deux bonnes durées de cuisson, très courte et très longue, et tout ce qui est entre les deux le change en caoutchouc. Je préfère la courte. Quadrillez le corps au couteau, frottez-y un peu d'épices apaisantes et posez-le sur le gril le plus féroce de la maison, le temps de dire son nom deux fois. Il se recourbe, il noircit sur les bords, il est cuit. Les cuisiniers du sud lui donnent une heure dans un ragoût. Ils ont tort, mais d'une manière intéressante." },
    [18241] = { "Le rouget est un poisson côtier, nommé pour la rougeur de ses ouïes, qui s'efface une fois pêché et cuit, comme la plupart des choses. Il n'a besoin de rien. Un filet, une poêle chaude, et la retenue de laisser la peau tranquille jusqu'à ce que la poêle la lâche. J'ai vu des cuisiniers attraper toutes les épices de l'étagère avec ce poisson, par nervosité. Un bon rouget n'est pas un problème à résoudre. C'est un poisson qu'on laisse en paix." },
    [18242] = { "Fumer à chaud, c'est fumer à une chaleur qui cuit en même temps, plus rapide que le fumage à froid et moins indulgent. Les épices fortes vont sur la perche d'été. Puis la perche va au plus épais de la fumée, où la chaleur la cuit à coeur dans le temps qu'une fumée froide mettrait à peine à la colorer. Restez près d'elle. Elle est cuite quand la chair s'effeuille à l'endroit le plus épais, et peu après, elle est sèche. C'est le seul poisson que je confierais au sac d'un soldat, et je l'ai confié à plusieurs." },
    [18243] = { "Le nagenuit est un lutjan pêché après la tombée du jour, ce qui explique les horaires des pêcheurs et leur humeur. La soupe, c'est le poisson et de l'eau de source, rien d'autre, et c'est exactement assez. Faites frémir le lutjan jusqu'à ce que la chair glisse des arêtes, et retirez chaque arête avant que le bouillon retourne sur le feu. Gardez la marmite là où une bulle crève de temps à autre, pas plus souvent, et le bouillon reste clair. S'il se trouble, vous l'avez fait bouillir. S'il est clair, levez-le à la lumière et accordez-vous un peu de fierté, brièvement." },
    [18244] = { "Pocher, c'est l'art de cuire dans une eau qui ne bout jamais tout à fait, et c'est l'art le plus négligé de toute cuisine. Le saumon solécaille, des mers chaudes, est riche et tendre, et se déferait sous une méthode plus rude. Amenez l'eau à frissonner, non à bouillir, descendez-y le poisson et laissez-le. Quand il devient opaque, sortez-le. L'eau ne doit pas une seule fois avoir élevé la voix." },
    [18245] = { "Du homard pince-noire, des côtes froides du nord, mijoté dans de l'eau de source et rien d'autre. Un homard n'a besoin d'aucune aide, seulement de respect. Amenez l'eau au frémissement et donnez-lui le homard entier. Il est cuit quand la carapace rougit, et pas un souffle plus tard. Décortiquez-le, et ne remettez la chair dans le bouillon que pour la réchauffer. Un homard cuit deux fois est une insulte. Un homard cuit une fois et réchauffé dans son bouillon est un ragoût." },
    [18246] = { "Le grand barracuda est le seul poisson que je découpe comme du boeuf, parce qu'il se taille en steaks et s'y comporte comme eux. Épices fortes et épices apaisantes, les premières pour la vigueur, les secondes pour les manières, pressées sur les deux faces du steak. Une poêle aussi chaude que vous l'osez, les deux côtés saisis bien bruns, puis laissez-le sur la planche un moment avant le couteau. Les pêcheurs du grand sud les remontent au filet à grands cris. Je les préfère dans une assiette, en silence, comme un steak doit se manger." },
    [18247] = { "Du saumon blanchécaille, un poisson des rivières froides, cuit entier avec des épices apaisantes dans un four plus tiède que chaud. Un poisson entier cuit de façon égale, là où un filet se dessèche sur les bords, et la peau garde le jus là où il doit être. Glissez une lame le long de l'arête : quand la chair s'en détache d'un seul morceau, le poisson est cuit. La recette se vend à Feralas, et je ferais le voyage pour elle, si Feralas était plus près." },
    [20626] = { "Une soupe d'Undermine, vendue en Tanaris par un gobelin nommé Jabbey, qui n'en a jamais plus d'un exemplaire à vendre et goûte la rareté plus que la soupe. La soupe vaut mieux que le gobelin. La chair de palourde piquante et les épices fortes vont dans le lait glacé, et la marmite se réchauffe avec grand soin, car le lait se venge du cuisinier négligent en tranchant. À Undermine, on la sert brûlante, pour montrer qu'on le peut. Je recommande de la manger à une température qui ne réclame pas de guérisseur." },
    [20916] = { "Une truite à la tête argentée couleur de mithril, ce qui explique le nom, et au caractère assorti, ce qui explique les bandages des pêcheurs. C'est un poisson de montagne, au sang froid dans tous les sens du terme. Gardez la peau, et nappez-lui le dos de la graisse de la poêle pendant qu'elle cuit. Sa chair est pâle et fine. La tête reste en place pour la table. Une truite sans sa tête a l'air gênée, et le cuisinier qui l'a servie aussi." },
    [21143] = { "Un biscuit du Voile d'hiver, vendu quelques semaines par an par des marchands souriants vêtus de rouge, et fait par des enfants qui en mangent la moitié avant qu'il n'atteigne le four. Les épices spéciales en sont tout l'intérêt : chaudes, douces et vives, et elles doivent être fraîches, car l'épice éventée a le goût de l'an dernier. Un oeuf lie le tout. Sortez les biscuits tant que le coeur cède encore sous le doigt, car ils continuent de durcir en refroidissant. Un biscuit cuit dur au four est une arme au matin." },
    [21144] = { "Le lait de poule est la boisson du Voile d'hiver, et la raison pour laquelle tant de matins du Voile d'hiver commencent tard. L'oeuf est battu dans le lait glacé avec les épices spéciales jusqu'à ce que le tout soit pâle, épais, et sente l'intérieur d'un bon buffet. L'eau de vie spéciale vient en dernier. Mesurez-la comme si les invités vous regardaient, ce qu'ils font. Servez-le froid, dans de petites tasses, et ne remplissez pas les tasses de ceux qui ont commencé à chanter." },
    [21175] = { "De la viande d'araignée blanche, pressée en saucisse et enseignée par tous les maîtres cuisiniers du royaume comme s'il s'agissait d'une chose ordinaire. Elle ne l'est pas. La chair d'araignée est douce et fine, plus proche du crabe que du porc, et elle ne prend aucune épice parce qu'elle n'en a nul besoin. L'art est dans le pressage : assez serré pour tenir, assez lâche pour rester tendre. Bien des élèves pâlissent au mot araignée. Je leur demande s'ils ont déjà mangé du crabe, et j'attends." },
    [22480] = { "La viande de loup tendre vient des loups du Berceau-de-l'Hiver et des contrées froides, où une bête vit lentement et garde sa graisse. C'est la meilleure viande de loup du monde, et elle est gâchée chez la plupart des cuisiniers. Des épices apaisantes, une saisie brève et féroce, puis un repos aussi long que la cuisson. Un cuisinier qui a ruiné cent loups filandreux en Elwynn comprendra enfin, avec celui-ci, ce qu'il cherchait." },
    [22761] = { "La recette de ce plat est entre les mains d'un diablotin, dans les ruines de Hache-tripes. Il ne s'en sépare qu'au terme d'une joyeuse poursuite à travers des salles pleines de satyres très en colère. Je le sais parce qu'un de mes élèves a fait cette course et en est revenu avec la recette, une démarche boiteuse et une opinion des diablotins que je partage. La racine de courante pousse à l'ombre de ces ruines et a le goût, bien cuite, de la meilleure racine dont vous ignoriez l'existence : terreuse, douce et un peu fumée. Pelez-la, taillez-la épais pour que le dehors caramélise avant que le dedans soit cuit, et donnez-lui des épices apaisantes et un four lent, jusqu'à ce qu'une fourchette y entre sans résistance. La surprise, c'est qu'une chose si bonne vienne d'un endroit si mauvais. J'enseigne la recette volontiers. Je n'enseigne pas la course, et j'ai conseillé à mon élève de ne jamais la refaire." },
    [24418] = { "Épais, dit-il, et ce n'est pas un mensonge : du crocilisque en abondance, avec des épices apaisantes, mijoté jusqu'à tenir plus de la purée que de la soupe. La garnison de Theramore en vit tout l'hiver d'Âprefange et jure que c'est la seule chose chaude du marais. Elle a raison. Le danger d'un ragoût aussi dense, c'est que la chaleur s'amasse au fond de la marmite, alors gardez-y une cuillère de bois en mouvement. La plupart des ragoûts ratés meurent là." },
    [24801] = { "Cette recette ne se vend pas. Elle s'enseigne, par les cuisiniers du Cercle cénarien en Silithus, et seulement à ceux qui ont survécu à un désert qui veut leur mort. Je ne suis jamais allé en Silithus. Je n'ai pas besoin d'y être allé pour savoir que la chair de ver des sables est un défi : dense, pâle, et friande de sable dans chaque repli. Lavez-la bien au-delà du moment où l'eau coule claire, car le sable se cache dans ce qui a l'air propre. Hachez-la avec les épices apaisantes et façonnez de petites boulettes, pressées fort pour qu'elles gardent leur forme dans la fumée, puis posez-les sur une grille haut au-dessus d'un feu bas. Le dehors prend la fumée et le coeur prend la vapeur, et une fois prêtes, elles sont fermes, parfumées et entièrement débarrassées du sable, ce qui est le véritable exploit. Le Cercle garde jalousement cette recette, et je l'en estime. J'ai gardé pire pour moins." },
    [25659] = { "Dirge Quikcleave tient une cuisine à Gadgetzan, en plein désert, où il cuit le chimaerok au carburant de fusée des gobelins et fait payer le privilège. J'ai toutes les raisons de mépriser cette recette. Je n'y parviens pas. Le filet de chimaerok est la meilleure viande de Kalimdor, dense et douce, tirée de bêtes si lointaines que seuls les braves ou les affamés en rapportent. Du sel de Fonderoc venu des mines des nains, des épices fortes, et le carburant, qui ne parfume pas la viande mais flatte le feu jusqu'à une chaleur qu'aucun charbon honnête n'atteint. Mettez beaucoup de distance et très peu de carburant. Dirge vous dirait le contraire. Dirge a moins de sourcils que moi. Les côtelettes en sortent noircies et juteuses et, je l'avoue, c'est ce qu'un gobelin a fait de mieux." },
    [25704] = { "La sagerelle fumée est un plat d'Austrivage, et ce qu'Austrivage a de meilleur, ce qui place la barre bas, mais elle est noblement franchie. Le poisson vit parmi la sauge au bord des lacs de Hautebrande, et sa chair en garde le parfum. Le fumage doit donc être froid et lent, sinon l'herbe brûle avant que le poisson soit cuit. Poudrez-le d'épices douces et gardez le feu qui couve, jamais en flammes, jusqu'à la tombée du jour. Les fermiers la vendent à leurs fenêtres. Les cuisiniers de Hurlevent ont la méthode par écrit. Les fermiers n'en ont jamais eu besoin." },
    [25954] = { "La grande sagerelle, c'est la sagerelle devenue adulte, avec davantage de tout, y compris l'odeur des herbes qui bordent son lac. Les épices fortes la mettent en avant sans l'enterrer. Couchez le filet côté peau et laissez-le jusqu'à ce que la peau sonne sous l'ongle, puis retournez-le un instant, pas plus. Délice est un mot fort pour un poisson. J'ai goûté celui-ci, et je ne le retire pas." },
    [470359] = { "Une bisque de homard pince-noire à l'eau sacrée de Stratholme, qu'on me dit potable, même si j'ai lu l'étiquette deux fois sans en être convaincu. Où se vend la recette, je ne l'ai pas encore appris. Celui qui l'a écrite avait de l'eau sacrée à écouler. Cela fonctionne. Cette eau est très propre et très douce, et elle laisse au homard toute la parole. Faites frémir, tamisez, et ne demandez pas à quoi d'autre cette eau a servi." },
    [470370] = { "Une nourriture de soldat venue de Silithus, faite pour la route. Personne ne m'a encore montré qui en vend la recette : c'est un trou dans mon catalogue, non dans mon savoir. Le rouget pend au-dessus d'une fumée lente et froide jusqu'à devenir aussi sec que la route qui l'attend, et pas davantage, sinon ce n'est plus que de l'écorce. Pas d'épices. Les soldats qui l'ont rapporté à Hurlevent voulaient mon approbation. J'ai corrigé la fumée et je le leur ai rendu, ce qui les a plus surpris que ne l'avait fait le désert." },
    [1225758] = { "Le steak de rôdeur, c'est du tigre, ce que le nom est trop poli pour dire. Les steaks sont taillés généreux, frottés de sels sacrés, puis laissés tranquilles un bon moment avant qu'on allume le feu. Pendant ce temps, le sel travaille en silence, fait monter le jus et pose la viande. Ensuite, un fer brûlant, brièvement, de chaque côté. J'ai entendu des chasseurs soutenir qu'un tigre se cuisine en colère. Les chasseurs devraient chasser, et laisser le fourneau aux cuisiniers." },
    [1225759] = { "Filet de flanc, un nom qui bégaie un peu, et un plat auquel rien ne manque. Le flanc de loup rouge est frotté de sels sacrés, dont le clergé vous dira qu'ils sont bénis et les marchands qu'ils sont chers. Les deux ont raison. Le sel tire l'eau de la viande et la resserre, si bien qu'elle cuit vite. Un steak béni trop cuit reste trop cuit. La Lumière ne le sauvera pas, et moi non plus." },
    [1225760] = { "Une omelette d'oeufs géants assaisonnée de sels sacrés, que quelqu'un a décidé d'appeler un lever de soleil. C'est la couleur : un jaune très vif, un blanc pâle, et une pincée de sel que le clergé a béni et que les marchands ont tarifé en conséquence. Gardez le feu doux, sinon le jaune se ternit. Un lever de soleil cuit trop vite devient midi, et personne n'écrit de poèmes sur midi. Je la sers aux prêtres, qui apprécient la plaisanterie, et aux paladins, qui ne l'apprécient pas." },
    [1225762] = { "Le festin de loche est le banquet d'un cuisinier qui avait beaucoup de poisson et l'ambition d'un seul raptor. Douze jaune-queues tachetés, trois morues rochécaille et quatre portions de raptor, avec des épices exquises, qui méritent leur nom au comptoir, sinon toujours dans la poêle. Les poissons sont grillés entiers et le raptor rôti, et l'astuce, comme pour tout festin, est que tout arrive en même temps. Les morues, qui sont épaisses, ouvrent le travail. Les jaune-queues, qui sont rapides, le ferment. Le raptor repose pendant que les poissons cuisent, ce qui arrange tout le monde. Disposez le tout sur la plus grande planche que vous possédiez, le raptor au milieu comme un général et les poissons autour en rangs. Un festin est une représentation. Le public la mange. À vous ensuite de saluer et de manger ce qui reste, c'est-à-dire en général la morue." },
    [1225763] = { "Un banquet n'est pas un plat. C'est une campagne. Douze homards pince-noire, quatre portions de tortue, trois ailes de busard et une bourse d'épices exquises, ainsi nommées parce que le marchand qui les vend a besoin d'un mot pour le prix. Les homards sont pochés, la tortue mijotée, le busard rôti, et le tout porté à table en même temps, ce qui est la véritable difficulté. Chaque partie doit finir au même instant, alors commencez par la plus lente, la tortue, et finissez par la plus rapide, les homards, sortis dès qu'ils rougissent. J'ai cuisiné un banquet de ce genre pour la noblesse de Hurlevent, et voici ce que j'en ai appris : les invités se souviennent du homard, et le cuisinier se souvient du minutage. Personne ne se souvient du busard. Cuisez-le bien quand même. Il se trouve toujours quelqu'un pour remarquer un raccourci." },
    [1229737] = { "Avant le plat, il y a le feu, et avant le feu, il y a un cuisinier qui sait le bâtir. Du bois sec, posé en croix avec de l'air entre les pièces, et la flamme portée au bas du tas, jamais au sommet. Puis laissez-le tranquille. Un cuisinier qui tisonne un jeune feu n'a pas appris à attendre. Un cuisinier qui en fait un brasier rugissant est un fanfaron. Le bon feu pour cuisiner est celui qui a cessé de vouloir vous impressionner et s'est installé en braises." },
    [1247741] = { "Un poisson que je n'ai pas encore vu au marché de Hurlevent, même si les pêcheurs en parlent comme de tous les poissons qu'ils n'ont pas pris. Le flétan est un poisson large, blanc et généreux, et celui-ci, armé d'épines, se défend, me dit-on, au bout de la ligne comme en cuisine. Taillez-le épais, cuisez-le doucement, et éprouvez-le du doigt : quand la chair se sépare en lamelles, il est cuit, et une minute plus tard c'est de la craie. Quand on m'en apportera un, j'en dirai davantage, et je le dirai le premier." },
    [1249957] = { "Le pacifique est la fleur pâle qui pousse au bord de toutes les routes, et les trolls Frostmane de Dun Morogh en font ce thé avant d'attaquer nos nains. Je trouve cela étrangement rassurant. Du pacifique dans de l'eau de source, portée juste sous l'ébullition et laissée jusqu'à prendre un or pâle. Retirez-la du feu avant la première bulle, car une fleur bouillie perd sa douceur et ne garde que sa tige. Bien fait, c'est la tasse la plus paisible du royaume. Les trolls, de toute évidence, n'en ont jamais bu." },
    [1249958] = { "Le mage royal est une herbe qui a une haute opinion d'elle-même, et le thé royal est du mage royal infusé dans du lait glacé, ce qui donne aussi au lait une haute opinion de lui-même. On chauffe doucement le lait et on y laisse l'herbe jusqu'à ce qu'il prenne une teinte violette pâle et l'odeur d'un beau jardin. Ne le faites pas bouillir. Le lait bouilli forme une peau, et une peau sur un thé royal est une honte, et des plus répandues. Je le sers aux nobles, qui goûtent l'ironie moins que moi." },
    [1249959] = { "De la vietérule infusée dans du jus de melon, ce qui est une drôle de façon de faire du thé, et une bonne. On chauffe le jus de melon jusqu'à ce qu'il fume tout juste, et la vietérule, lavée et tranchée, y reste jusqu'à ce que le jus fonce à la couleur d'un beau chêne. Filtrez-le au linge. Laissez la racine trop longtemps, et la terre où elle a poussé vient s'asseoir à votre table sans y être invitée. Les murlocs de Hautebrande portent cette recette, ce que je prends pour la preuve que même les murlocs ont des après-midi." },
    [1249960] = { "Un thé pour après le combat, à en croire son nom, fait de nectar sucré et de pâlerette. La pâlerette est l'herbe que les voleurs mâchent pour passer inaperçus, ce qui me semble une curieuse chose à donner aux blessés. Le nectar est chauffé jusqu'à fumer, jamais jusqu'à bouillir, et la pâlerette sort dès que la couleur tourne, car ensuite elle ne donne plus que de l'amertume. Aucun marchand ne m'a encore offert cette recette. Quand l'un d'eux le fera, je l'achèterai, et j'offrirai à boire au guérisseur qui l'a écrite." },
    [1249961] = { "De la soleillette infusée dans du jus de baie lunaire, ce qui est une plaisanterie sur le soleil et la lune que la recette ne prend pas la peine d'expliquer. On chauffe le jus et la soleillette y infuse jusqu'à ce que la boisson prenne l'or d'un soleil de fin de journée. Filtrez et servez tiède, jamais chaud. C'est une boisson gaie, ce qui est rare, et je n'ai rien de cinglant à en dire, ce qui l'est plus encore." },
    [1249962] = { "Un thé de sauge-argent des montagnes et de rosée matinale. Les sages de Hurlevent le boivent pendant qu'ils réfléchissent, c'est-à-dire toute la journée, et en portent le coût au compte de la Couronne. La rosée n'est chauffée que jusqu'à ne plus être froide, et la sauge-argent n'y reste que jusqu'à ce que la rosée prenne un léger vert. C'est un très bon thé. C'est aussi une façon coûteuse de se sentir sage, qui est la plus répandue." },
    [1249963] = { "Un frappé fait avec une glande à venin, dont le vendeur m'a assuré qu'elle était sans danger, avec l'aplomb d'un homme qui n'en avait pas encore bu. La glande est brisée dans l'eau de source avec les épices douces, et le tout passe par un linge fin, si bien que la boisson garde le mordant du venin et laisse le venin derrière elle. Servez-le froid. La première gorgée est un avertissement et la seconde un plaisir, ce qui est le bon ordre pour l'un comme pour l'autre. Je ne vends rien de tel. Je le pourrais un jour, si le vendeur survit." },
    [1249964] = { "Gélatineux, dit-il de lui-même, et c'est le nom le plus exact de ce chapitre. De l'ichor d'araignée, des épices douces et du lait glacé, secoués jusqu'à ce que l'ichor cesse de bouder au fond et consente à être une boisson. Servez-le aussitôt, car il ne reste pas conciliant longtemps. Je ne l'aurais pas inventé. J'ai cependant regardé un gnome en boire trois, ce qui en dit plus long, à mon sens, sur les gnomes que sur le frappé." },
    [1249965] = { "Je n'essaierai pas de prononcer le nom de cette boisson. J'ai entendu un murloc essayer, et cela ne s'est bien passé ni pour lui ni pour moi. L'aileron doit être frais, et secoué fort dans le jus de melon avec les épices fortes, assez longtemps pour que le jus se trouble légèrement et prenne la mer. C'est sucré, puis brûlant, puis quelque chose que je ne peux appeler que côtier. Les murlocs le boivent pour insulter le reste du monde. C'est, je l'avoue, une insulte bien faite." },
    [1249966] = { "Un frappé avec un croc dedans. J'ai lu la recette deux fois, puis une troisième avec mes lunettes. Du nectar sucré et des épices fortes, avec un grand croc moulu fin et mêlé au tout. Le croc donne à la boisson un corps crayeux et en fait la favorite des gens qui combattent les ours. Filtrez bien. Une boisson qui crisse sous la dent est une réclamation qui attend, et je n'accepte pas les réclamations." },
    [1249967] = { "Une boisson avec un sac de flammes dedans, ce que les mages de feu tiennent pour une recommandation. Le jus de baie lunaire et les épices apaisantes vont dans le verre, et le sac est percé d'une épingle au-dessus du verre, une seule fois, à bout de bras. Secouez fort et buvez vite, avant que la chaleur ne se décide. C'est la seule boisson que je connaisse qui réchauffe les mains de l'intérieur. Les mages de feu du quartier des Mages la commandent au pichet, ce qui vous dit tout ce qu'il faut savoir des mages de feu." },
    [1249968] = { "Une boisson nommée d'après son pire ingrédient, ce qui est une rare honnêteté dans une recette. La serre cruelle est moulue en poussière, car un éclat dans la gorge est une piètre façon de finir une soirée, puis mêlée à la rosée matinale avec une main lourde d'épices apaisantes. L'épice est une offrande de paix. La serre la refuse. Ce que vous buvez est amer, sombre et vaguement hostile. Je ne l'ai jamais servi pour le plaisir. Je le sers aux élèves qui se vantent, et ils se vantent moins ensuite." },
    [1250142] = { "Les mini-burgers sont petits et nombreux, comme les jeunes cuisiniers aiment tout. Le cerf est haché fin avec des épices fortes et pressé en galettes de la taille d'une paume. Pressez-les une fois et plus jamais : une galette pressée deux fois laisse son jus dans la poêle, où aucun invité ne le goûtera. Je n'approuve pas la nourriture conçue pour être mangée debout. J'approuve ceux-ci, même si je les mange assis, au couteau." },
    [1250143] = { "Une pamplona, c'est de la viande aplatie, farcie et roulée, et celle-ci est faite de busard, la seule chose qui prenne de l'envergure dans ce plat. Les ailes doivent être désossées et battues fin sous une poêle lourde avant que les épices apaisantes n'y passent, puis roulées serré et ficelées. C'est un travail minutieux, et c'est dans le travail minutieux qu'on éprouve un cuisinier. Un four doux, puis le couteau. Les rondelles montrent votre travail au couteau. Veillez à ce qu'elles montrent quelque chose que vous signeriez." },
    [1250144] = { "Hachee est un vieux mot de ferme pour un ragoût lent de viande hachée, et ici, la viande est de la chauve-souris. Je n'aurais pas choisi la chauve-souris. La chauve-souris ne m'aurait pas choisi non plus. Des ailes hachées, des épices apaisantes, et un feu doux pendant presque toute une soirée, jusqu'à ce que les tendons rendent les armes et deviennent une chose qu'on peut servir à un invité. Celui qui l'a inventé était pauvre et malin. Je respecte les malins, et j'ai appris, avec les années, à pardonner aux pauvres." },
    [1250145] = { "De la tortue mijotée plutôt que tamisée, ce qui en fait un plat de paysan, et il ne s'en porte pas plus mal. De la tortue et une main généreuse d'épices apaisantes, mijotées jusqu'à ce qu'une cuillère partage la viande sans aide. Ne la tamisez pas. La texture est tout l'intérêt d'un ragoût, et un ragoût de tortue en a beaucoup, dont une part voulue. Servez-le épais, dans des bols, sans vous excuser d'être honnête." },
    [1250146] = { "Au poivre, annonce le nom, et la recette n'en contient pas un grain. Elle a du flanc de loup rouge et des épices apaisantes, et l'épice porte si bien la chaleur que personne ne regrette le poivre. Le flanc est un morceau travailleur, qui veut une poêle féroce et une main rapide. Ce que la viande laisse dans la poêle compte autant que la viande : grattez-le et nappez-en le steak avant de servir. Ne le découpez jamais dans la poêle où il a saisi. La poêle se souvient de la chaleur, et la viande aussi." },
    [1250147] = { "Bruscitti. J'ai cherché le mot dans trois langues sans le trouver dans aucune. Le plat est assez simple pour s'expliquer seul : de la viande de grand ours tranchée fin, empilée avec des épices apaisantes entre les tranches, et rôtie lentement jusqu'à ce que la pile ne fasse plus qu'un. L'astuce est de trancher à froid, car la viande tiède se déchire sous la lame. Celui qui a nommé ce plat voulait faire étranger. Le plat, lui, n'a rien à cacher, et je l'aime mieux que son nom." },
    [1250148] = { "Un steak de cerf servi fumant, c'est-à-dire servi aussitôt, comme tout steak devrait l'être et comme presque aucun ne l'est. Faites pénétrer les épices apaisantes au plus profond du cerf, puis couchez-le sur un fer assez chaud pour qu'il siffle dès que la viande le touche. Retournez-le une fois. Puis portez-le droit à table. S'il arrive sans vapeur, il a attendu là où il n'aurait pas dû, et quelqu'un dans votre cuisine vous doit des excuses, et très probablement un autre steak." },
    [1250149] = { "Le tigre de ce plat n'a pas été pris par la foudre, quoi qu'en dise le nom. Il a été pris par un chasseur et une longue attente, et la vitesse appartient à la cuisson. Frottez le tigre d'épices apaisantes et donnez-lui un feu si féroce qu'il faut le surveiller, pour un temps si court que tourner le dos est une faute. Puis posez-le sur une planche tiède et laissez-le là. Un steak tranché aussitôt saigne sur la planche et arrive sec, et personne ne se souvient du feu." },
    [1250150] = { "Une recette que j'ai entendu décrire sans jamais la voir vendue, et c'est l'espèce la plus dangereuse. Le raptor a fini de bouillir bien avant d'arriver dans la poêle, alors le nom parle de l'épice, dont la quantité fait peur. Cuisez les côtelettes à feu doux jusqu'à ce que la viande quitte l'os, puis finissez-les à grand feu pour la croûte. Ne les servez qu'à ceux qui les ont demandées. Je ne dis pas cela de tous les plats." },
    [1250151] = { "La poitrine est le morceau d'un cuisinier patient, et la poitrine d'ours celui d'un saint. C'est la partie la plus dure de l'animal, tout en travail et en vieux muscle. Frottez-la d'épices fortes et donnez-lui le plus petit feu que vous puissiez entretenir, et une journée entière. Quelque part dans la soirée, elle rend les armes et se défait sous la fourchette. Je ne peux pas vous dire l'heure. Je peux vous dire que le cuisinier qui vérifie trop souvent n'y arrive jamais." },
    [1250152] = { "Préhistorique, comme si le raptor attendait depuis le commencement du monde qu'on l'effiloche. Peut-être était-ce le cas. C'est un plat de temps, non d'adresse : du raptor, lourd d'épices apaisantes, sur des braises dont vous vérifiez sans cesse qu'elles vivent encore, du matin jusqu'aux lampes du soir. N'y touchez pas. Quand il est prêt, il se rend. Défaites-le à la fourchette, jamais à la lame. Un couteau en fait du raptor tranché, et le raptor tranché est un plat moindre." },
    [1250153] = { "Rouladen est un mot nain, ou une prétention naine sur un mot, et le plat est de la viande roulée : du raptor taillé fin, tartiné d'épices fortes, roulé et ficelé. Plus la tranche est fine, plus vite la chaleur gagne le centre, et un rouleau épais brûle dehors avant que son coeur soit cuit. Colorez d'abord les rouleaux sur toutes leurs faces, puis baissez le feu et laissez-les en paix. Coupez la ficelle avant qu'ils ne partent à l'assiette. Une ficelle dans une assiette est l'aveu d'un cuisinier qui a cessé de faire attention." },
    [1250154] = { "Deux fois épicé, et pour une fois un plat dit la vérité sur lui-même. Le raptor est frotté une fois avant d'être tranché, et une fois après la cuisson. C'est le seul plat où l'épice de la fin a raison d'être : la seconde couche est pour le mordant, non pour la croûte. La chair de raptor est maigre et sèche vite. Tranchez-la en travers des fibres, assez fin pour voir une bougie au travers, et donnez-lui le feu le temps d'un souffle, pas davantage. Une recette que je n'ai pas inventée, et que j'aurais inventée, avec le temps." },
    [1250155] = { "Les oeufs brouillés sont la première épreuve de la patience d'un cuisinier, et les oeufs brouillés géants sont la même épreuve dans une plus grande poêle. Des oeufs géants et des épices fortes, battus ensemble et remués sur un feu doux, lentement, sans relâche, jusqu'à ce qu'ils se rassemblent en grumeaux tendres. Une poêle chaude en fait du caoutchouc. Une poêle douce en fait de la soie. La plupart des cuisiniers ne supportent pas de remuer si longtemps. La plupart des cuisiniers ne devraient pas approcher un oeuf géant." },
    [1250156] = { "Une recette qui traîne dans les nids de raptors, ce qui est soit une plaisanterie, soit un avertissement. Les bouchées se font avec l'oeuf, non avec la bête, et un oeuf de raptor est plus lourd et plus riche que tout ce qu'une poule a jamais pondu. Assaisonnez le blanc plus généreusement que la décence ne le voudrait, et laissez le jaune tranquille, comme toujours : il est assez riche sans vous. Cuisez les bouchées petites et vite. Un oeuf de raptor cuit lentement tourne au caoutchouc par pure rancune. C'est sa mère qui le lui a appris, je n'en doute pas." },
    [1250157] = { "Une omelette de petit déjeuner, avec un oeuf et une quantité franchement alarmante d'épices douces. Celui qui a écrit cette recette s'est réveillé affamé et en colère. Le secret de toute omelette tient à la chaleur et à la vitesse : battez l'oeuf bien lisse, donnez-lui une poêle déjà chaude, et gardez une fourchette en mouvement pendant qu'il prend. Pliez-la tant que le coeur est encore tendre. La recette a été trouvée dans les Carmines, dans le nid d'un condor, ce qui explique la colère, sinon les épices." },
    [1250158] = { "Linguine est le nom d'une longue pâte plate, et la recette, à son honneur, ne prétend pas en contenir. Elle a de la chair de palourde piquante, taillée en longues lanières pour faire illusion, et tournée dans les épices apaisantes. Une poêle chaude, presque pas de temps, et droit à table, car la palourde cuite un instant de trop durcit. Dans l'assiette, les lanières s'emmêlent comme des pâtes et se mangent comme des palourdes. J'approuve la supercherie." },
    [1252566] = { "Fantaileron. Quelqu'un a donné ce nom à un poisson, et quelqu'un d'autre l'a approuvé. Gnolls et murlocs promènent la recette dans leurs sacs à travers les Carmines, et ni les uns ni les autres ne sont connus pour leur cuisine, alors ils l'ont volée à quelqu'un qui l'était. Le poisson est un petit bijou, et fragile. Des épices douces, à peine, et une poêle chaude, brièvement. Le nom promet de la fantaisie. Le plat livre un souper, ce qui vaut mieux et se révèle bien plus fiable. Mangez-le aussitôt." },
    [1255241] = { "Un ragoût fait d'une fleur gangrenée que quelqu'un a purifiée, ce qui, m'assure-t-on, en refait une herbe et non plus une menace. Je crois les druides sur parole en pareille matière, et sur très peu d'autres. La viande de cerf lui donne du corps. L'oeuf géant entre en dernier, hors du feu et en mince filet, sinon le bouillon se brouille au lieu de devenir soyeux. On le cuisine pour ceux qui reviennent de Gangrebois, et ils méritent une cuisine plus aimable que la forêt qu'ils ont quittée." },
    [1262978] = { "Macaron est le murloc qui tient la cuisine de la Confrérie défias, au fond des Mortemines. On me dit qu'il cuisine une louche dans une main et un couperet dans l'autre, sans trop se soucier de celui qu'il emploie sur les visiteurs. Sa recette a été rapportée de la mine par des aventuriers qui la lui ont prise, et je l'ai étudiée avec un intérêt professionnel dont je ne suis pas fier. Deux portions de viande mystère et une de kodo épais, rôties lentement avec des épices apaisantes jusqu'à ce que le kodo cède et que la viande mystère ait pris une teinte sombre. C'est un festin, c'est-à-dire qu'il se partage sur un plat commun, ce que je trouve peu hygiénique et que les Défias, sans doute, trouvent nécessaire. Le plat est excellent. Le cuisinier est un murloc et un criminel. Je l'engagerais demain, s'il laissait son couperet à la porte." },
    [1263067] = { "Un four en fer, dit la recette, puis elle demande de la farine, de l'eau de source et des épices apaisantes, et pas un gramme de fer. Je l'ai relue plusieurs fois. Je crois que la pâte est travaillée avec l'épice et cuite dans le four neuf, pour culotter le fer avant qu'on y mette quoi que ce soit qui vaille d'être mangé. Quel que soit son secret, c'est une recette de maître, et je ne la possède pas encore, ce qui m'agace plus que je ne puis le dire poliment." },
    [1270632] = { "Un biscuit conçu pour les petits animaux qui suivent les aventuriers partout, et composé, je le note, de rien d'autre que de farine, ce qui vous dit à quel point on consulte les petits animaux. La farine se travaille d'une main légère et cuit jusqu'à un or pâle. Les bestioles en raffolent. J'ai vu un chat en manger un. Le chat m'a regardé ensuite comme s'il en attendait davantage, ce qui est la seule critique qu'un animal de compagnie ait jamais rendue." },
    [1270633] = { "Un soufflé, c'est un oeuf qu'on a convaincu de se tenir debout, et le soufflé de Mur-Céleste, nommé pour quelque hauteur que je n'ai pas visitée, se tient plus haut que la plupart. Les blancs sont montés en neige ferme et incorporés d'une main légère aux jaunes et à un peu de farine, puis la porte du four reste fermée. C'est la règle. Ouvrez la porte et il retombe, et il ne remontera plus, ni pour vous ni pour personne. Le soufflé est le seul plat qui boude pour toujours." },
    [1270635] = { "« La saison des crabes », dit le nom de la quête qui enseigne ce plat, un bien grand titre pour ramasser des pinces sur une plage. On tire la chair des pinces, on la lie à la farine et on la frit une bouchée à la fois. La farine n'est là que pour tenir chaque bouchée en un seul morceau. Une pincée, pas un grain de plus. Une bouchée qui a le goût du pain vous a menti sur la plage." },
    [1283400] = { "Un compagnon doit apprendre que tous les bois ne se valent pas, et le bois d'étoile est la leçon. Il brûle d'une chaleur blanche et propre que le bois commun n'atteint jamais, et il y arrive vite. La recette est apparue dans les Cavernes des lamentations, parmi des druides qui avaient d'autres soucis en tête. Bâtissez-le comme le feu de base, mais n'y cuisinez pas avant que les flammes soient tout à fait retombées, car cette chaleur punit le cuisinier pressé. Un meilleur feu ne fait un meilleur cuisinier que si celui-ci l'attend." },
    [1291341] = { "Les bûches épaisses sont le feu d'un maître : une épreuve à allumer, et une fois prises, elles gardent la même chaleur toute la soirée, régulières comme un âtre. Un débutant veut des flammes. Un spécialiste veut des braises qui ne changeront pas d'avis au milieu d'un rôti, et seules les bûches épaisses les lui donnent. Empilez-les pour que l'air monte par le milieu, et attendez qu'elles prennent. La recette n'est pas encore arrivée sur mes étagères, et j'ai interrogé chaque marchand de passage. J'ai vu des cuisiniers qui croyaient ne pas en avoir besoin, et ils n'ont jamais tout à fait été des spécialistes." },
    [1294014] = { "Une confiture des baies d'Hyjal, qui poussent sur les pentes d'une montagne que les druides disent sacrée et qui est surtout très froide. Des baies et des épices apaisantes, réduites sur un feu doux. Pour l'éprouver, refroidissez une soucoupe et déposez-y un peu de confiture : si elle se ride quand on la pousse, elle est prête. Trop liquide, vous avez fait une sauce. Trop ferme, vous avez fait une brique. On l'appelle patte-douce, d'après les ours qui pillent les buissons. Les ours ont raison sur les baies." },
    [1295805] = { "Un ragoût du rivage, fait de ce que le rivage offre, c'est-à-dire du crabe et, à mon éternel regret, des yeux de murloc. Les yeux donnent du corps au bouillon, comme dans le ragoût de la Marche de l'Ouest, et j'ai appris à cesser de discuter avec eux. La viande de crabe tendre entre en dernier et ne cuit qu'à la chaleur du bouillon, ce qui la garde douce. Des épices fortes tout du long. Le résultat est saumâtre et riche, et sent la mer avant que quiconque l'ait nettoyée." },
    [1295834] = { "Une recette des Rives Claires, vendue par une femme qui n'a vu aucune raison de lui donner un nom plus grandiose, et elle avait raison. De la viande de sanglier, en bonne quantité, avec une pincée d'épices douces, rôtie sur l'os jusqu'à ce que la graisse crépite. C'est tout. J'ai passé ma vie à apprendre aux cuisiniers à ne pas en faire plus, et voici une fermière qui n'a jamais eu besoin de leçon. Laissez reposer avant de découper. La cuisine simple ne pardonne rien, et c'est pourquoi elle est si rarement bien faite." },
    [1319313] = { "Un poisson qui porte une armure, ce qui semble juste, vu ce qui arrive à ceux qui n'en portent pas. Glissez un couteau lourd sous les plaques par la queue, là où elles se chevauchent, et elles se soulèvent une à une. La chair dessous est aussi ferme qu'une queue de homard, et presque aussi douce. Assaisonnez-la d'épices apaisantes et cuisez-la à chaleur modérée, avec la patience que les plaques vous ont déjà enseignée. Un poisson qui a mis si longtemps à se forger une armure peut bien mettre un moment à la quitter." },
  },
  eunice = {
    [2538] = { "Le premier plat de tout cuisinier, vivant ou non. On l'apprend sur la route avec un couteau et un feu, parce qu'il y a toujours un loup et toujours quelqu'un qui a faim. Prêtez l'oreille. La viande de loup siffle quand elle rencontre la chaleur et se tait quand l'extérieur est saisi. Retournez-la une fois, au silence. Mes élèves veulent la piquer. Je les laisse faire, une fois, puis je les laisse manger ce qu'ils ont piqué." },
    [2539] = { "Je l'enseigne le deuxième jour, après le loup grillé, pour que mes élèves apprennent que l'épice n'est pas une correction. Frottez-la dans la viande avant le feu. Ajoutée à la fin, elle sent l'épice et le loup, deux étrangers à la même table qui ne se parlent pas. Ajoutée au début, elle sent le souper. Les vivants me disent que la différence est tout aussi nette sur la langue." },
    [2540] = { "En Lordaeron, on rôtissait le sanglier à la moisson, dans une fosse derrière la grange, ou derrière l'auberge, ou derrière la grange de quelqu'un. Je me souviens nettement de la fosse et pas du tout de la grange. Ici, c'est un plat simple pour les jours simples. Rôtissez la viande en morceaux, jamais entière : un sanglier entier prend la journée, et ceux qui l'attendent ne vous la donneront pas. Quand la graisse commence à sentir le sucré plutôt que l'âcre, c'est prêt." },
    [2541] = { "Les coyotes mangent tout ce que le monde laisse tomber, et leur viande se souvient de chaque repas. Elle ne prend pas d'épices, seulement une poêle chaude et un cuisinier qui ne s'en excuse pas. Saisissez-la jusqu'à ce que les bords se recourbent et que l'odeur passe du sang à la noisette grillée, puis retirez-la du feu et n'y touchez plus. Un steak de coyote n'est jamais tendre, me disent les vivants en mâchant. Il est honnête, et la nourriture honnête tient un voyageur debout sur une longue route." },
    [2542] = { "Une tourte de ferme du sud, et nous en faisions une toute pareille en Lordaeron, avec du foie de porc, les jours où le boucher était passé. Je revois le plat à tourte. Il était bleu, avec un éclat sur le bord, il refroidissait sur le rebord d'une fenêtre, et je ne sais pas de quelle fenêtre il s'agissait. Le foie de Broche-tripes est fort et sombre. Rincez-le à l'eau froide avant de le cuire, pour calmer l'amertume, puis assaisonnez-le d'épices douces et faites-le cuire à four doux. Le foie cuit vite sent le fer et devient gris. Le foie cuit lentement sent quelque chose de riche et de doux, comme la terre tiède après la pluie, et c'est là qu'il est prêt. Mes élèves la préparent pour les vivants de passage, et les vivants la mangent comme si elle leur était familière. Peut-être l'est-elle, pour eux." },
    [2543] = { "Un ragoût de fermier du sud, fait de ce que la terre donne quand elle donne très peu : du vautour, le groin d'un Broche-tripes et un oeil de murloc, dont je ne m'excuserai pas. Nous avions un ragoût de ce genre en Lordaeron, fait de ce que les champs et la rivière voulaient bien laisser. Je me souviens de la marmite. Je me souviens qu'elle était noire et lourde, et que quelqu'un se brûlait toujours la main avec. La main de qui, je ne saurais plus le dire. L'oeil donne du corps au bouillon, alors ne l'enlevez pas pour épargner un invité délicat. Les invités délicats peuvent bien jeûner. Laissez mijoter jusqu'à ce que le vautour renonce, ce qui prend plus longtemps que vous ne le croyez. Les voyageurs du sud me disent que les fermes y sont vides maintenant. Le ragoût a survécu aux fermes, comme les ragoûts savent le faire." },
    [2544] = { "Austrivage faisait des beignets de crabe les jours de fête, et les femmes se disputaient sur l'épice par une fenêtre ouverte, même si je ne sais plus à qui était la fenêtre. Je me souviens mieux des disputes que des beignets. Nettoyez bien la chair de clampant, ajoutez une pincée d'épices douces et pressez le tout à la main. Faites-le frire jusqu'à ce que le dehors prenne. S'il s'effondre, pressez plus fort la prochaine fois. S'il rebondit, pressez moins. La dispute est facultative." },
    [2545] = { "Fendez la pince avant qu'elle ne rencontre le feu, pour que la chaleur atteigne la chair au lieu de la cuire à la vapeur dans sa propre carapace. Une pincée d'épices douces dans la fente. Un feu bref et chaud. Vous entendrez la chair grésiller dans la carapace, un petit bruit affairé, et quand il s'arrête, la pince est cuite. Tirez la chair à la fourchette. La carapace va aux apothicaires, qui veulent tout." },
    [2546] = { "Pas de sauce, seulement l'épice, un feu bas et un après-midi entier, comme les fermes les cuisaient à la moisson. J'ai oublié laquelle. Les côtes sont prêtes quand les os dépassent d'un doigt aux extrémités et que l'odeur est passée de la viande à quelque chose de proche du pain grillé. Je les sers sur du papier, à des gens qui mangent avec les doigts et se moquent qu'on les voie. À Fossoyeuse, c'est presque tout le monde." },
    [2547] = { "De l'araignée et du condor, mijotés ensemble. Le condor est coriace et l'araignée ne l'est pas, alors le condor entre d'abord et l'araignée bien plus tard. Mettez-les ensemble et vous sentirez l'araignée trop cuire, une note aigre et piquante, bien avant que le condor soit près d'être prêt. C'est un plat du sud, de gens qui avaient plus d'araignées qu'ils n'en voulaient. Je comprends très bien ces gens-là." },
    [2548] = { "Je retourne très souvent ces côtes aux épices fortes, pour que la graisse arrose la viande en fondant. Retourner, c'est la recette. Une côte laissée à elle-même brûle dessous et boude dessus. Une côte souvent retournée en sort luisante et généreuse. Un fermier m'a appris cela, un voisin, je crois, avec une barbe rousse, ou une grange rouge. Je donne celle-ci aux élèves qui croient que cuisiner, c'est attendre. Ce n'est pas cela. C'est faire attention pendant qu'on attend." },
    [2549] = { "Herbes aromatiques de Stormwind, dit le sachet, et elles sentent exactement un marché dont je me souviens. Où se tenait ce marché, je ne le sais plus. Le loup s'en moque. Enfilez la viande en laissant de l'espace entre les morceaux, pour que la chaleur atteigne chaque face, et écoutez la graisse crachoter. Quand elle cesse de crachoter et se met à chanter, retournez les brochettes. La première va à celui qui attend depuis le plus longtemps." },
    [2795] = { "Un plat de nains, ce qui veut dire qu'il arrive avec une histoire sur le grand-père qui l'a inventé, et que l'histoire change selon celui qui la raconte. Je ne prends pas parti. Les côtes et la bière sont honnêtes, quel que soit le premier à les avoir cuites. Tous les nains dont j'ai entendu parler arrosent dès la première minute, puis accusent le feu de la suite. Rôtissez les côtes à nu jusqu'à ce que la graisse coule claire, et alors seulement commencez la bière, un peu à la fois, pour qu'elle devienne un glaçage. Quand elle sent le sucre brûlé, c'est allé trop loin. Quand elle sent le pain et la fumée, c'est parfait. Les gardes noirs demandent celui-ci par son nom, ce qu'ils ne font même pas pour leurs sergents. Je le prépare les jours de fête, et les jours qui en ont besoin." },
    [3370] = { "Le crocilisque arrive à Fossoyeuse depuis les Paluns, par des gens qui préfèrent ne pas dire comment. Je ne demande rien. La viande est pâle et ferme, plus poisson que bête, et elle veut une pincée d'épices et très peu de temps. Cuisez-la une fois. Le crocilisque réchauffé sent le marais, et personne n'a commandé le marais. Servez-le tout de suite, à qui se tient le plus près." },
    [3371] = { "Chaque automne, les fermes de Lordaeron faisaient le boudin, et chaque automne la grand-mère de quelqu'un connaissait la seule bonne façon de le faire. La mienne ne jurait que par le thym. Ou par la sauge. J'en ai été sûre pendant des années. Ici, c'est l'ichor d'araignée qui lie le tout, là où le sang le faisait autrefois, et la Société royale des apothicaires m'assure qu'il est sans danger pour les vivants, ce qu'elle ne dit pas de grand-chose. Les vivants en redemandent, et c'est la seule critique qui m'intéresse. Pochez les boudins avant qu'ils ne voient la poêle. Un boudin qui éclate a été rempli par quelqu'un de pressé." },
    [3372] = { "Des ailerons de murloc et des épices fortes, mijotés jusqu'à fondre dans le bouillon et le laisser épais et riche, comme un fond d'os. L'odeur est celle de la mer à marée basse, ce qui paraît désagréable et ne l'est pas, une fois que l'épice s'en mêle. Les murlocs de la côte des Pins argentés protesteraient, s'ils savaient. Ils protestent contre presque tout, bruyamment, et j'ai cessé d'écouter depuis longtemps." },
    [3373] = { "De la viande de crocilisque tendre et des épices fortes, réduites jusqu'à ce que le bouillon soit épais et assez sombre pour napper une cuillère. La couleur vous renseigne, et l'odeur aussi : quand elle passe du marais à la noisette grillée, vous y êtes. Remuez par le fond, toujours. Je ne peux pas goûter un gombo, mais je sens un gombo brûlé depuis l'autre bout de Fossoyeuse, et tout le monde aussi, me dit-on." },
    [3376] = { "Je fais celle-ci avec un oeuf de raptor et des épices fortes. L'oeuf est plus riche que celui d'une poule et prend plus lentement, alors prenez patience avec le coeur. Battez-le fort, cuisez-le vite, pliez-le tendre. Ce qu'elle a d'étrange, disent les vivants, c'est d'être si bonne. Je les crois, parce qu'ils se taisent, puis regardent l'assiette comme si elle leur devait une explication. Je la fais pour mes élèves le jour de leur premier vrai succès." },
    [3377] = { "Des pattes d'araignée, la chair tirée et pressée en galettes avec des épices fortes, frites jusqu'à ce que l'extérieur croustille et que le coeur reste tendre. Le fondant doit rester au coeur. S'il coule dans la poêle, vous l'entendrez siffler et le sentirez brûler, et la galette est perdue. Faites-les frire à chaleur régulière, pas féroce. J'en fais par plateaux entiers. Les araignées sont la seule chose que Fossoyeuse peut toujours offrir à un invité." },
    [3397] = { "Les ours du sud sont plus grands que les nôtres, et leur viande est plus sombre, avec une odeur de pin et de terre mouillée que les épices fortes tranchent. Saisissez le steak jusqu'à ce qu'il sente la fumée et le fer, puis laissez-le reposer longtemps. Un gros steak continue de cuire après le feu, et plus d'un cuisinier en a gâché un à force de le fixer. Je dis à mes élèves de s'éloigner et de compter jusqu'à cent, puis de me dire quel goût il a. La plupart arrivent à quarante." },
    [3398] = { "Les lions des Tarides sont maigres et doux près de l'os, alors les côtelettes restent sur l'os. Des épices fortes, un feu modéré, et beaucoup de retournements. La force du piquant, c'est aux autres d'en juger, et ils ne s'en privent pas. Les orcs de la Croisée réclament plus d'épices à chaque fois et les trolls moins, alors je fais deux poêles et je les laisse se disputer pour savoir laquelle est la bonne." },
    [3399] = { "Du lion cuit en steak plutôt qu'en côtelettes, avec des épices apaisantes pour arrondir la douceur de la viande. L'épice apaisante sent le clou de girofle et la pierre tiède. Frottez-la, saisissez le steak fort, laissez-le reposer aussi longtemps que vous l'avez saisi. Tranchez en travers des fibres, sinon il se défend dans la bouche. Le nom a été écrit par quelqu'un qui l'avait mangé et qui était trop occupé pour trouver mieux." },
    [3400] = { "De la tortue et des épices apaisantes, mijotées des heures, puis passées au tamis jusqu'à être lisses comme de la crème. Le tamis, c'est la recette. L'odeur pendant que ça mijote est chaude et ronde, comme des clous de girofle dans une pièce fermée, et elle ralentit les gens qui passent devant ma cuisine. J'aime un plat qui ralentit les gens. Ici, tout le monde est si pressé d'aller quelque part où il est déjà allé." },
    [4094] = { "Il y a plus de busards que de cuisiniers dans les Tarides, et les cuisiniers leur ont trouvé un usage. L'aile veut des épices fortes, une longue chaleur douce pour attendrir les tendons, puis une flamme brève et féroce pour cloquer la peau. On entend le changement. La graisse cesse de chuchoter et se met à crépiter. Servez-les chaudes et en quantité. Personne n'a jamais mangé une seule aile de busard." },
    [6412] = { "Une recette elfique, venue d'un arbre si haut que les elfes de la nuit, dit-on, cuisinent dans ses branches. Je n'y suis jamais allée, et l'on ne m'y attend pas. La recette m'est parvenue par trois marchands, dont deux honnêtes. Enfilez les pattes d'araignée sur une brochette et donnez-leur une chaleur vive et brève, jusqu'à ce que les carapaces craquent comme des brindilles dans un feu. Ce bruit est le signal. Après lui, chaque instant vous coûte." },
    [6413] = { "Les cuisiniers de Durotar ont envoyé ce plat vers le nord par les premiers zeppelins, et Fossoyeuse l'a adopté. La surprise est dans le dard. Cuit jusqu'à passer du verre à la craie, il perd son venin et garde un croquant agréable. Pas assez cuit, il garde son venin, et la surprise est d'un autre genre. Cela s'entend. Un dard cru cliquette dans la poêle. Un dard cuit ne bouge plus. Les voleurs en achètent par poignées et les mangent dans l'escalier." },
    [6414] = { "Les taurens de Mulgore rôtissent le kodo comme ils font la plupart des choses, lentement et sans histoires. Je le cuisine de la même façon. Le kodo est un grand animal lent, et sa viande reste dure jusqu'à ce qu'elle en décide autrement. Une pincée d'épices, un feu doux et un après-midi. C'est prêt quand ça sent l'herbe tiède et la fumée. Je ne peux pas le goûter, alors j'ai demandé à un marchand tauren, qui m'a dit que le mien était presque aussi bon que celui de sa mère. J'ai choisi de croire que le presque était de la politesse." },
    [6415] = { "Les furies ne sont que dents et colère, et leur chair est ce qu'elles ont de plus tendre. Un filet se défait si on le regarde trop longtemps. Assaisonnez-le légèrement, posez-le côté peau dans une poêle chaude, retournez-le une fois. L'odeur est douce et brève, partie en un souffle. Quand elle s'efface, le poisson est cuit. La recette vient de Sombrivage, par une elfe qui ne voulait de moi qu'un prix juste, ce qui est plus rare que cela ne devrait l'être." },
    [6416] = { "Du trotteur et de la pomme, le premier ragoût des Tarides. La pomme entre avec la viande et fond jusqu'à disparaître, et quand on ne la trouve plus dans la marmite, le ragoût est prêt. Le trotteur est un oiseau têtu. La pomme l'adoucit. Je le prépare pour les orcs qui regrettent leur pays et pour les trolls qui regrettent un pays disparu, et ils le mangent tous de la même façon, très vite." },
    [6417] = { "Les Tarides m'ont appris celui-ci, et Fossoyeuse l'a adopté, parce que nous ne manquons pas de rats non plus, même si les nôtres ne sont pas bons à manger et que les rats fouisseurs des Tarides le sont. Faites-les mijoter longtemps, jusqu'à ce que la viande tombe des petits os, et retirez les os avec patience et une cuillère. Mes élèves font la grimace. Je les fais manger. Puis ils le préparent eux-mêmes, pour les élèves suivants, et les grimaces continuent." },
    [6418] = { "Les Tarides m'ont appris celui-ci, avec la patience et le respect de tout ce qui y survit. Une queue de lézard-tonnerre est un muscle plein, enveloppé d'une peau comme du vieux cuir. Cuisez-la dans sa propre graisse avec des épices fortes jusqu'à ce que la peau craque sous une cuillère. Si elle plie, ce n'est pas cuit. Si elle éclate, c'est parfait. Les orcs la mangent entière. Moi, je la coupe en rondelles, par égard pour le mobilier." },
    [6419] = { "Il y avait des cerfs dans les bois au-dessus de la ferme, et mon père, ou mon oncle, ou un voisin avec un arc, en abattait un chaque automne. Le visage s'est effacé. L'odeur de la viande dans la poêle, non. La venaison est maigre et fière, et veut beaucoup d'épices et très peu de feu. Retirez-la tant que le coeur est encore sombre. Une viande maigre cuite à coeur ne sent plus que le regret." },
    [6499] = { "Les palourdes sont honnêtes. Elles vous disent quand elles sont prêtes, pour peu que vous gardiez le nez au-dessus de la marmite. La vapeur sent d'abord le sucré, puis la mer, et c'est le moment de les sortir. Les palourdes ne pardonnent rien, et j'apprécie cela chez un aliment. Un voyageur descendu du zeppelin en a mangé deux bols debout à mon comptoir, puis il a demandé s'il y en avait un troisième. Il n'y en avait pas. J'en prépare davantage, maintenant." },
    [6500] = { "Les gobelins mettent trop de chaleur dans tout, palourdes comprises. Je l'enseigne avec la chaleur corrigée. De la chair de palourde relevée, des épices fortes, un feu chaud sans être furieux. L'odeur vous dira quand vous arrêter : quand l'épice cesse de sentir le cru et se met à sentir le grillé, retirez la poêle. Une palourde cuite avec fureur devient du cuir. Les gobelins vous vendraient le cuir en l'appelant moelleux." },
    [6501] = { "Quelqu'un, à Austrivage, vendait de la soupe de palourdes à une porte près du port, et l'odeur courait le long du quai. Je me souviens exactement de l'odeur, et pas du tout de la porte. Chauffez doucement le lait, ajoutez la chair de palourde et une pincée d'épices douces, et restez sous le frémissement. Le lait qui bout tranche, et on le sent arriver, une note aigre dans la vapeur. Si vous la sentez, recommencez." },
    [7213] = { "Une palourde géante est dense et douce, et à Baie-du-Butin, on la saisit dans les épices fortes pour les pirates. Tranchez-la fin avant que la chaleur ne la touche, pour que l'épice la traverse, puis cuisez-la fort et vite. La fumée vous fera pleurer. C'est ainsi que vous saurez que l'épice suffit. Quand la fumée se dissipe, le plat est prêt. Servez-le à quelqu'un qui a l'estomac solide et la mémoire courte." },
    [7751] = { "Les enfants en pêchent au bout de chaque ponton de Tirisfal, et je leur achète leurs seaux, parce qu'un enfant avec un poisson mérite une pièce. Cuisez-les entiers dans une poêle chaude, une poignée à la fois. Leurs yeux se troublent quand ils sont cuits, ce qui est le plus aimable des signaux : le poisson vous le dit lui-même. Les élèves qui ne savent rien faire d'autre savent faire cela, et je les fais commencer ici pour qu'ils aient de quoi être fiers." },
    [7752] = { "Le maquereau est gras, et la graisse est tout l'intérêt. Posez-le côté peau dans une poêle chaude et sèche et laissez sa propre graisse le cuire. L'odeur emplit la cuisine, monte l'escalier et gagne la rue, et quelqu'un descend toujours demander ce que c'est. C'est ainsi que je trouve la plupart de mes clients. Le poisson fait sa réclame mieux que moi, et il ne demande pas de gages." },
    [7753] = { "La vase est dans la peau, non dans la chair, et on la sent dès que le poisson rencontre la chaleur. Cuisez-le entier sur un feu modéré et ôtez la peau avant de servir. La chair dessous ne sent rien d'autre que le poisson, ce qui est exactement ce qu'on attend d'un poisson. Les pêcheurs de Tirisfal mangent aussi la peau. Ils disent qu'elle leur rappelle la rivière. Ils n'avaient pas besoin de me dire pourquoi." },
    [7754] = { "L'eau froide du loch donne un poisson plus ferme que les furies du sud, et les nains l'ont appelé un délice, ce qui, me dit-on, leur ressemble peu. Une pincée d'épices douces, un feu vif, et servez-le chaud. L'odeur est nette et froide, comme un matin au bord d'un lac. Je ne suis jamais allée au Loch Modan. Je suis allée au bord de lacs. J'imagine que c'est pareil, avec plus de cris." },
    [7755] = { "Le poisson-chat, c'était ce que la rivière nous donnait quand elle nous donnait quelque chose, et quelqu'un de ma famille le dépouillait sur la marche de derrière. Retirez toujours la peau. Elle sent le lit de la rivière, et le lit de la rivière n'est pas un souper. La chair dessous est blanche et douce et veut une poêle chaude et un seul retournement. J'entends encore ce couteau sur la marche. Je ne vois plus la main qui le tenait." },
    [7827] = { "Ferme, sombre et riche, plus viande que poisson, et il faut le cuire comme une viande : une saisie franche dehors et très peu au coeur. La couleur vous renseigne. Rose dedans, c'est juste. Gris, c'est trop. Je ne peux pas goûter la différence. Je peux la voir, et le visage de celui qui le mange la voit aussi. Le rose vaut un hochement de tête. Le gris vaut de la politesse, ce qui est pire." },
    [7828] = { "Ses écailles émousseraient un mauvais couteau, alors achetez-en un bon avant d'acheter le poisson. Retirez-lui ses écailles dehors, si vous pouvez. Les écailles vont partout et on les retrouve pendant des semaines. Puis une poêle chaude et un seul retournement. La chair se défait en feuillets blancs et nets et sent l'eau froide et le sel. Elle n'a besoin de rien. Je ne lui donne rien, et mes élèves apprennent que rien est parfois la chose la plus difficile à donner." },
    [8238] = { "Les poissons déviants viennent des bassins empoisonnés des Cavernes des lamentations, et ceux qui les ont empoisonnés ne voulaient pas les rendre délicieux. Ils le sont, un peu. Cuisez le poisson à coeur, avec des épices douces, et ne le laissez pas sous-cuit. Les apothicaires s'intéressent beaucoup à ce qu'il fait aux vivants. J'ai regardé. Je dirai seulement que c'est le seul plat que mes clients aient jamais mangé deux fois, pour voir ce qui se passerait." },
    [8604] = { "Un oeuf est la première chose que j'enseigne, parce qu'il vous dit tout par son odeur bien avant de vous dire quoi que ce soit par son goût. Quand la cuisine sent l'épice chaude et rien d'autre, il est cuit. Quand elle sent quelque chose de plus âcre, recommencez plutôt que de discuter avec lui. L'oeuf a toujours raison. Mes élèves le trouvent indigne d'eux. Un oeuf en a humilié davantage que n'importe quel sanglier." },
    [8607] = { "Ni épices ni sauce, seulement la fumée et le temps. C'est la nourriture des gens qui vont quelque part. Coupez la viande dans le sens des fibres et suspendez-la haut au-dessus d'un petit feu de bois vert, là où la chaleur n'arrive pas et où la fumée fait tout le travail. Au matin, les lanières doivent plier avant de casser. J'en prépare pour les gardes noirs, sur la route du Sépulcre. Ils n'ont pas besoin de manger, et ils en prennent trois chacun." },
    [9513] = { "Du chardonnier infusé dans de l'eau de source jusqu'à ce qu'il tourne au vert doré, puis filtré. Tous les voleurs de Fossoyeuse en boivent avant le travail, et Fossoyeuse compte beaucoup de voleurs. Ils viennent à mon comptoir à des heures étranges et paient le compte exact. Ne le laissez pas infuser trop longtemps. Il devient amer, et les voleurs, qui l'aiment amer, le boiront quand même et repartiront sans un mot." },
    [13028] = { "Un peu de dorépine va loin, ce qui vous dit sa force. Infusez-la dans une eau tout juste retirée du feu jusqu'à ce qu'elle prenne la couleur du vieux laiton, puis filtrez fort. L'odeur est vive et claire, comme une épée qu'on astique. Tous les gardes noirs des remparts en boivent, et aucun n'en a besoin. Ils ne le goûtent pas mieux que moi. Je crois qu'ils aiment la chaleur de la tasse entre leurs mains. Je ne leur ai jamais demandé." },
    [15853] = { "Un steak tout simple, pris au flanc d'un loup, avec une pincée d'épices et rien derrière quoi se cacher. C'est ce qui en fait une épreuve. Saisissez vite, laissez reposer longtemps, tranchez fin en travers des fibres. Je le juge à sa couleur et au visage de celui qui le mange, puisque je ne peux faire autrement. Je fais cuisiner ce steak à mes élèves jusqu'à ce qu'ils ne tressaillent plus au sifflement de la poêle. Certains mettent une semaine. L'un d'eux a mis un an." },
    [15855] = { "Les camps de Strangleronce rôtissent le raptor en gros morceaux, et moi aussi, parce que le raptor est maigre et qu'un gros morceau garde son coeur moelleux. Des épices fortes dehors, un feu vigoureux, puis éloignez-le de la chaleur pour finir. L'odeur passe du métal à la fumée, puis aux noix grillées. Quelque part autour des noix, retirez-le. Le raptor s'est bien battu. Ne le laissez pas gagner à table." },
    [15856] = { "Des loups rouges du grand sud, plus gras que les loups gris des Pins argentés, avec des côtes qui ont besoin de temps pour fondre. Des épices fortes et un feu vif, puis de la patience. La graisse coule claire avant de fumer, et c'est le moment entre les deux qu'il vous faut. Les gardes noirs qui reviennent du sud en rapportent, enveloppées dans un linge, comme s'ils avaient trouvé un trésor. Pour une cuisinière, ils en avaient trouvé un." },
    [15861] = { "De la viande de tigre, de l'eau de source et des pommes, le ragoût de Strangleronce. Faites d'abord dorer la viande, puis ajoutez l'eau et les pommes et laissez mijoter jusqu'à ce que le fruit soit passé dans le bouillon. L'odeur devient sucrée, puis profonde, puis sucrée de nouveau. La seconde douceur veut dire que c'est prêt. Des trolls me l'ont appris, des Darkspear en route vers un endroit plus chaud. Ils disaient qu'il a le goût de chez eux. Je les ai crus sur parole." },
    [15863] = { "Les trolls du marais appellent ceci une tourte, et ils le disent gentiment. De la viande mystère et des épices fortes, cuites jusqu'à ce qu'il ne reste aucun doute sur rien. Je sens ce qu'était la viande, ce qui est plus que les trolls ne peuvent en dire, et je la sers quand même. Cuisez à coeur, puis recommencez. Quoi qu'elle ait été, elle a fait un long voyage, et elle mérite une fin franche." },
    [15865] = { "De la viande mystère mijotée dans de la bière naine, et pour moi, il n'y a de mystère ni dans l'une ni dans l'autre. Je sens exactement ce qu'était la viande. Je sens la brasserie d'où vient la bière, et ce qu'on a renversé sur son sol. Faites-le cuire longtemps et doucement, et ne le laissez jamais bouillir, sinon la bière aigrit et vous le sentirez depuis l'escalier. Écumez la marmite pendant qu'elle mijote. La bière rend la viande sombre et tendre, et donne au bouillon une amertume que les vivants semblent beaucoup aimer. Les apothicaires, qui devraient être plus avisés, en mangent des quantités et refusent de dire ce qu'ils croient qu'il contient. J'en ai vu toute une tablée se disputer là-dessus pendant une soirée. J'ai cessé de le leur dire. Ils l'apprécient davantage sans savoir, et tout le monde aussi, je crois." },
    [15906] = { "La viande mystère entre dans ce plat, et je préfère taire ce que mon nez m'en dit. Ce sont les Tarides qui m'ont appris ce plat, non Lordaeron, qui n'a jamais rien mangé qui se défende à ce point. Je ne peux pas vous dire à quel point ce chili est fort. Je peux vous dire que les épices grillées me piquent les yeux, la seule chose que j'en ressente encore. Le dernier tauren qui a goûté le mien a posé sa cuillère avec beaucoup de précaution et demandé de l'eau d'une voix que je ne lui connaissais pas. Percez le sac de flammes avant qu'il n'entre, sinon il se percera tout seul. J'en fais quand un équipage de zeppelin rentre d'une longue traversée dans le froid. Faites-le pour des gens que vous aimez, et prévenez-les. Puis regardez leur visage. Le plat est réussi quand ils se taisent." },
    [15910] = { "Les kodos de Désolace sont plus lourds que ceux des Tarides, bien que la terre leur donne peu, et leur viande est la plus dense que je connaisse. Les taurens m'ont appris ce ragoût, et je n'y ai jamais rien changé, parce qu'il n'y a rien à changer. De la viande de kodo épaisse, des épices apaisantes et de l'eau de source, et toute une journée sur un feu bas. Vous sentirez l'odeur changer : crue, puis herbeuse, puis profonde et brune, comme un champ après la pluie. Quelque part dans la soirée, la viande se défait en fils au contact d'une cuillère. C'est le moment, et aucun autre. Je le prépare les jours les plus froids pour les gardes noirs sur les remparts au-dessus, et je le monte moi-même. Ils n'en ont pas besoin. Ils font la queue quand même, et ils sont très silencieux en mangeant." },
    [15915] = { "De la viande de crabe tendre et beaucoup d'épices fortes, remuées sans cesse dans une poêle assez chaude pour vous faire reculer. L'épice doit cuire dans le crabe, non rester posée dessus. La force du piquant, je la laisse aux trolls, qui le mangent sans ciller, et aux orcs, qui le mangent en faisant semblant de ne pas ciller. Je sers les deux avec le même visage impassible. Mangez-le avec les doigts. Personne dans ma cuisine ne vous jugera." },
    [15933] = { "Un oeuf géant nourrit une table, et à Fossoyeuse, une table, c'est quiconque se tient le plus près du fourneau. Les oeufs viennent des grands oiseaux du nord, et la recette des marchands de Gangrebois et du Berceau-de-l'Hiver, qui ne disent jamais où l'on trouve les oeufs. Battez l'oeuf avec les épices apaisantes jusqu'à ce qu'il soit lisse et pâle, puis versez-le dans la plus large poêle que vous ayez, sur un feu modéré, et ramenez les bords à mesure qu'ils prennent. L'odeur vous guide : chaude et ronde d'abord, puis noisette sur les bords. Noisette, c'est le moment de plier. Brun, c'est trop tard. Portez-la à table à deux mains. J'ai vu toute une patrouille de gardes noirs en partager une en silence, avec un grand soin, comme un trésor. Un instant, c'en était un. Puis ils en ont demandé une autre, et c'était le meilleur moment." },
    [15935] = { "Tous les nouveaux cuisiniers de Tirisfal en font, parce que les chauves-souris sont partout et qu'il ne reste pas grand-chose d'autre. J'en ai préparé plus que n'importe quel plat de ma première vie. Incisez la peau de l'aile et posez-la sur une plaque bien chaude, côté peau, puis n'y touchez plus. Elle parle pendant qu'elle cuit. Quand le sifflement devient crépitement, retournez-la une fois, et plus jamais. Servez-la à qui a encore faim. Ici, à Fossoyeuse, il y a toujours quelqu'un." },
    [18238] = { "Ferme et gras, venu des eaux chaudes au large de Tanaris, il est d'autant meilleur qu'on en fait moins. Couchez-le dans une poêle chaude et laissez-le jusqu'à ce que le bord blanchisse, puis retournez-le. L'odeur, quand il est cuit, est nette et vive, comme une brise marine qui n'a pas encore rencontré les quais. Mes élèves veulent ajouter des choses. Je leur retire le pot d'épices et le leur rends une fois le poisson mangé. La plupart ne le redemandent jamais." },
    [18239] = { "Un gros poisson riche du sud chaud, taillé en tranches assez épaisses pour reposer comme une viande. Les épices apaisantes arrondissent sa richesse sans la cacher. Saisissez les tranches fort, laissez-les reposer, servez-les. L'odeur est si riche qu'elle en devient presque sucrée, et elle porte loin. Quand je cuis du barracuda, la file à mon comptoir commence avant que le poisson soit prêt. Elle ne commence jamais si tôt pour les plats dont je suis fière." },
    [18240] = { "Un instant ou une heure, rien entre les deux. Je choisis l'instant. Quadrillez le calmar au couteau, frottez un peu d'épices apaisantes dans les entailles et posez-le sur le gril le plus chaud que vous ayez. Il se recourbe comme s'il était surpris. Quand les bords noircissent, il est cuit. L'odeur est sucrée et fumée, et elle tire les clients de la rue comme une corde." },
    [18241] = { "Le rouget n'a besoin que d'une poêle chaude. Posez le filet côté peau et attendez qu'il se décolle tout seul. C'est toute la leçon, et la plupart des élèves mettent un mois à l'apprendre, parce qu'attendre est plus difficile que faire. L'odeur passe du cru au sucré, et les bords passent du translucide au blanc. Retirez-le alors. Il vous a dit tout ce qu'il savait." },
    [18242] = { "Fumée chaude et de près, pour que le poisson cuise en fumant. Frottez la perche d'épices fortes et suspendez-la juste au-dessus d'un feu fumeux. Surveillez la chair : quand elle passe de translucide à blanche, décrochez-la. Une perche fumée ainsi se garde des jours. J'en prépare pour les voyageurs qui prennent le zeppelin, qui ont toujours faim et sont toujours en retard, et qui la mangent avant que le zeppelin ait quitté la tour." },
    [18243] = { "Un lutjan pêché la nuit, de l'eau de source, et rien d'autre. Faites frémir le poisson doucement jusqu'à ce que la chair tombe des arêtes, puis retirez les arêtes avec soin. Le bouillon doit être assez clair pour qu'on lise au travers. Il ne sent presque rien, et c'est tout l'intérêt : une soupe nette et calme pour des gens qui ont eu une journée bruyante. Je la prépare pour moi, le soir, et cela ne me gêne pas de ne pas pouvoir la goûter." },
    [18244] = { "Une eau qui ne bout jamais tout à fait, pour un poisson qui se déferait sous toute chose plus rude. Amenez-la à frémir, descendez-y le saumon et laissez-le tranquille. Vous le verrez passer du vif au pâle, comme s'il rougissait à l'envers. Sortez-le alors. Pocher est ce que je fais de plus doux en cuisine, et c'est ce que mes élèves trouvent le plus difficile, parce qu'il ne se passe rien pendant si longtemps." },
    [18245] = { "Du homard pince-noire dans de l'eau de source, et c'est tout. Descendez le homard entier et sortez-le à l'instant où sa carapace rougit. Retirez la chair de la carapace et réchauffez-la dans le bouillon. Ne le faites jamais bouillir deux fois. L'odeur d'un homard qui va trop loin est aiguë et reconnaissable entre toutes, comme du cuivre chaud, et une fois qu'on l'a sentie, on ne la laisse plus jamais arriver. Je l'ai laissée arriver une fois. C'était assez." },
    [18246] = { "Un grand barracuda est assez gros pour être découpé en steaks comme du boeuf, et il faut le cuire comme du boeuf. Des épices fortes pour le réveiller, des épices apaisantes pour le calmer, une saisie franche des deux côtés et un long repos. L'odeur est celle de la mer et d'une forge à la fois. Je le sers aux gardes noirs les soirs qui précèdent une longue patrouille. Ils ne disent rien, ce que disent les gardes noirs quand une chose est bonne." },
    [18247] = { "Un saumon entier des rivières froides, cuit au four avec des épices apaisantes à chaleur modérée. Entier, parce que la peau garde la chair moelleuse, comme un couvercle sur une marmite. Quand l'oeil blanchit et que la nageoire se détache au moindre contact, c'est cuit. La cuisine sent les rivières et l'épice chaude, et les apothicaires descendent emprunter des choses dont ils n'ont pas besoin, et repartent avec une assiette." },
    [20626] = { "Une soupe gobeline de Tanaris : de la chair de palourde piquante, des épices fortes et du lait glacé, chauffés ensemble sans jamais bouillir. Les gobelins la mangent brûlante, ce qui vous dit tout des gobelins. Gardez le feu bas et surveillez la vapeur. Quand elle sent la mer et l'épice chaude, et pas encore le lait brûlé, servez à la louche. Le gobelin qui la vend n'en garde qu'un exemplaire à la fois. Je l'ai acheté, alors il a dû s'en écrire un autre." },
    [20916] = { "Un poisson de montagne froid, à la tête d'argent et au caractère de bagarreur. Cuisez-la entière, avec la peau, dans une poêle chaude, et arrosez-la de sa propre graisse. Quand la peau cloque et que l'oeil blanchit, elle est cuite. Laissez la tête. Mes élèves demandent pourquoi. Je leur dis que le poisson s'est donné du mal pour la garder, et que le moins qu'on puisse faire est de la laisser venir à table." },
    [21143] = { "Le Voile d'hiver, en Lordaeron, sentait ces biscuits dans toutes les cuisines de la rue à la fois, ou du moins je le crois. Je me souviens si nettement de l'odeur qu'il m'arrive de la sentir à Fossoyeuse en plein été, ce qui ne peut pas être vrai. Des épices spéciales et un oeuf, travaillés ensemble et cuits jusqu'à ce que les bords foncent et que le coeur cède encore. Ils durcissent en refroidissant. J'en fais à chaque Voile d'hiver pour les enfants des équipages des zeppelins. Ils ne demandent pas pourquoi j'en fais autant." },
    [21144] = { "Le Voile d'hiver, et l'oncle de quelqu'un qui fait du lait de poule dans un grand saladier, trop fort, chaque année. Je ne vois pas son visage, mais je l'entends chanter. Un oeuf, du lait glacé, de l'eau-de-vie spéciale et des épices spéciales, battus jusqu'à ce que ce soit pâle et épais. L'eau-de-vie entre en dernier et avec modération, ce dont aucun oncle n'a jamais fait preuve. Cela sent la muscade, le bois tiède et un peu les ennuis. Servez-le froid et gardez un oeil sur le saladier." },
    [21175] = { "Les araignées sont la seule chose dont Fossoyeuse ne manque jamais. La viande d'araignée blanche est douce et délicate et ne prend aucune épice, ce qui est une grâce dans une ville qui sent tout. Pressez-la bien serrée à la main pour qu'elle tienne, et faites-la frire jusqu'à ce que le dehors croustille. Dans la poêle, écoutez la croûte claquer sous la cuillère. C'est le bruit le plus satisfaisant de ma cuisine, et mes élèves apprennent à l'attendre." },
    [22480] = { "Les loups des contrées froides vivent lentement et gardent leur graisse, et leur viande est la meilleure de tous les loups. Des épices apaisantes, une saisie brève et vive, un long repos. Vous sentirez quand c'est prêt : l'épice se réchauffe et la viande devient douce, comme une miche tout juste sortie du four. Mes élèves jurent qu'ils sentent la différence dès la première bouchée, et je les crois, parce qu'ils se taisent. Un cuisinier qui a affronté cent loups faméliques mérite celui-ci. Je le sers à mes meilleurs élèves." },
    [22761] = { "La recette vient d'un diablotin des ruines de Hache-tripes, qui entraîne quiconque la veut dans une longue course stupide. Un de mes élèves a fait la course et en est revenu avec la recette, deux nouvelles cicatrices et beaucoup à dire sur les diablotins. La racine de courante pousse dans l'ombre de ces ruines, et c'est la meilleure racine que je connaisse, terreuse et douce. Pelez-la, tranchez-la épais et rôtissez-la lentement avec des épices apaisantes jusqu'à ce que les bords foncent et que le coeur cède sous la fourchette. Vous sentirez quand c'est juste : comme des châtaignes au coin d'une rue en hiver. Ce n'est pas mon souvenir, c'est celui de mon élève, qui l'a si bien décrit que je le lui ai emprunté. Les gardes noirs l'aiment parce qu'elle les remplit. Les vivants l'aiment parce qu'elle a le goût, me disent-ils, d'un endroit sûr. J'en fais beaucoup." },
    [24418] = { "Du crocilisque à pleine marmite, des épices apaisantes, et un ragoût où une cuillère tient debout. Remuez par le fond, souvent, parce qu'un ragoût aussi épais attache et brûle là où vous ne le voyez pas, et l'odeur ne vous trahit que lorsqu'il est trop tard. Les soldats des marais le mangent dans des bols en fer-blanc sous la pluie, m'a-t-on dit. Mes gardes noirs le mangent dans des bols en fer-blanc au sec. Les bols en fer-blanc sont les mêmes partout." },
    [24801] = { "Le Cercle cénarien l'enseigne en Silithus à ceux qui ont fait leurs preuves dans le désert. Les soldats de la Horde l'ont rapportée parmi leurs cicatrices. La chair de ver des sables est dense, pâle et pleine de sable. Lavez-la jusqu'à ce que l'eau coule claire, hachez-la fin avec les épices apaisantes et roulez-la en petites boulettes bien serrées, pour qu'elles tiennent dans la fumée. Puis fumez-les lentement sur un feu bas. La fumée parfume le dehors pendant que la vapeur cuit le coeur, et l'odeur passe du cru au sucré, puis à quelque chose comme le grain grillé. Quand elle arrive au grain, elles sont prêtes. Je ne peux pas vous dire quel goût elles ont. Je peux vous dire qu'un soldat qui avait perdu trois amis dans ce désert en a mangé une assiette dans ma cuisine et a pleuré. Puis il m'a demandé la recette, et je la lui ai donnée." },
    [25659] = { "Un gobelin de Gadgetzan cuit le chimaerok au carburant de fusée, et les voyageurs de la Horde rapportent la recette comme on relève un pari. La mienne vient d'un tauren qui avait perdu ses sourcils et gardé son appétit. Le filet de chimaerok est bien loin pour un morceau de viande, les îles au large de Feralas, et il vaut chaque pas. Du sel de Fonderoc, des épices fortes et le carburant de fusée des gobelins, qui va sur le feu, jamais dans la nourriture. Reculez plus loin que la politesse ne le voudrait. La flambée dure un souffle et laisse une croûte qu'aucun charbon honnête ne pourrait faire. L'odeur emplit tout l'Apothicarium, et les apothicaires sortent de leurs salles pour se plaindre et restent pour manger. Je ne leur demande pas ce qu'ils en pensent. Je compte les assiettes." },
    [25704] = { "Les sagerelles viennent des lacs de Hautebrande, où ma famille allait l'été, je crois. Le poisson sent la sauge des rives, et la fumée fait ressortir cette odeur. De l'odeur, je suis sûre. Des étés, beaucoup moins. Une fumée basse, une pincée d'épices douces et un après-midi. Quand la chair dore et sent les herbes et la fumée de bois, c'est prêt. Je la fume par fournées, parce que les vivants l'achètent à pleins bras." },
    [25954] = { "La grande sagerelle, engraissée de la sauge de son lac, avec des épices fortes pour la réveiller. Saisissez le filet côté peau jusqu'à ce que la peau crépite, puis retournez-le le temps d'un souffle. L'odeur est le délice : verte, chaude et poivrée, tout à la fois. Je le prépare quand je veux que la cuisine sente autre chose que la ville au-dessus, c'est-à-dire presque tous les jours, pour être honnête." },
    [470359] = { "De l'eau sacrée de Stratholme, que les apothicaires m'ont tendue sans sourire. Je suis allée à Stratholme une fois, vivante, pour un marché ou un mariage, et je me souviens des cloches et du pain, et de rien d'autre. Maintenant, son eau fait une bisque. Du homard pince-noire, frémissant dedans jusqu'à ce que la carapace rougisse, puis tamisé jusqu'à être lisse. L'eau est très douce et très propre, et elle ne me brûle pas. Elle laisse le homard parler. J'écoute." },
    [470370] = { "Les soldats de Silithus en vivent, parce que ce rouget se garde en route, et personne ne m'a encore dit qui en vend la recette. Du rouget, fumé lentement jusqu'à être assez sec pour être emporté et encore assez tendre pour être mangé. Pas d'épices. La fumée et le temps font le travail. Je l'ai appris d'un apothicaire revenu du désert avec la méthode et pas grand-chose d'autre. Il disait que c'était la seule chose là-bas qui n'avait pas essayé de le tuer." },
    [1225758] = { "Du tigre, voilà ce que veut dire le nom, taillé épais et frotté de sels sacrés une heure avant la cuisson. Le tigre est une viande travailleuse, et le sel la calme. Puis un fer brûlant, une saisie brève et un long repos. Vous l'entendrez se détendre sur la planche, un léger affaissement, comme un chien qui se couche. C'est là qu'on tranche. Pas avant. Un tigre qui ne s'est pas posé ne se posera pas davantage à table." },
    [1225759] = { "Des sels sacrés, venus des églises des vivants, ce qui m'a fait rire la première fois que j'en ai tenu une bourse. Ce sont de bons sels. La Lumière n'a rien contre moi en cuisine. Frottez-les dans le flanc de loup rouge et laissez reposer une heure, puis cuisez vite. Le sel tire l'eau de la viande et la raffermit. Il ne me brûle pas, avant que vous ne demandiez. Mes élèves demandent toujours." },
    [1225760] = { "Des oeufs géants et des sels sacrés, dont on m'avait dit qu'ils me brûleraient et qui ne me brûlent pas. Cuisez-la lentement, pour que le jaune reste vif comme le matin. L'odeur est nette et simple, l'oeuf, le sel et la poêle. Je la prépare à l'heure que les vivants appellent l'aube, ce qui ne veut rien dire ici, par une habitude dont je ne me rappelle pas l'origine. Quelqu'un vient toujours la chercher. Je la sers sur une assiette blanche, pour que le jaune puisse se faire admirer." },
    [1225762] = { "Douze jaune-queues tachetés, trois morues rochécaille, quatre portions de raptor et des épices exquises, disposés sur la plus grande planche de la cuisine. Les morues d'abord, parce qu'elles sont épaisses. Le raptor rôtit et repose pendant que les poissons cuisent. Les jaune-queues en dernier, parce qu'ils sont rapides, et dès que leur peau se décolle du gril, ils sont prêts. L'odeur d'un festin de poisson est une marée qui monte : d'abord la mer, puis la fumée, puis l'épice. Quand l'épice arrive, commencez à porter les plats. Je l'ai préparé pour les équipages des zeppelins à la fin d'une longue saison, et les gobelins, qui ne sont pas sentimentaux, se sont assis à mon comptoir et ont mangé pendant une heure sans parler d'argent une seule fois. C'est la seule fois que j'ai vu un gobelin oublier de marchander. C'était le festin, pas moi." },
    [1225763] = { "Un banquet, c'est beaucoup de travail, et celui-ci plus que la plupart. Il demande douze homards pince-noire, quatre portions de tortue, trois ailes de busard et des épices exquises, qui sont surtout exquises par leur prix. La tortue mijote le plus longtemps, alors elle commence en premier. Le busard rôtit pendant que la tortue mijote. Les homards viennent en dernier, pochés et sortis dès que leur carapace rougit, avant que l'odeur ne tourne au cuivre. Tout doit arriver à table ensemble. Vous saurez que c'est prêt quand la salle sentira à la fois la mer, la forêt et l'âtre. Je l'ai cuisiné deux fois, pour les officiers de la Dame noire, qui n'ont rien dit et ont tout mangé. La seconde fois, l'un d'eux est descendu ensuite me dire que c'était très bon. Il n'avait pas mangé de homard depuis le temps où il était vivant. Il se souvenait de ce qu'un homard était censé être." },
    [1229737] = { "Avant le plat, le feu. Du bois simple, empilé sans serrer pour que l'air puisse circuler, allumé par le bas et laissé tranquille. Vous entendrez quand il sera prêt : le crépitement s'apaise en un bourdonnement sourd et les flammes s'enfoncent dans les braises. Cuisinez sur les braises, jamais sur les flammes. J'enseigne cela en premier, avant le loup, parce qu'un cuisinier sans feu est un invité, et je ne garde pas d'invités dans ma cuisine." },
    [1247741] = { "Une recette sans vendeur, pour l'instant, pour un poisson que je n'ai jamais vu. On me dit que le flétan épineux est large et blanc et armé le long du dos, ce qui est la façon dont les poissons disent qu'ils préféreraient ne pas être mangés. Cuisez-le en morceau épais, doucement, jusqu'à ce que les feuillets commencent tout juste à se séparer. Je l'écris pour que le premier cuisinier qui en attrape un sache par où commencer. Dites-moi quelle odeur il avait." },
    [1249957] = { "Du pacifique infusé dans de l'eau de source jusqu'à ce que l'eau prenne la couleur de la paille. Ne le faites pas bouillir, sinon il sentira le foin et rien d'autre. Laissez-le infuser, et il sentira la lisière d'un champ le soir, qui reste la meilleure odeur que je connaisse. Les trolls Frostmane en font, dit la recette. J'en prépare pour les apothicaires, qui ont plus besoin de paix que quiconque et en reçoivent moins." },
    [1249958] = { "Du mage royal infusé dans du lait tiède jusqu'à ce que le lait prenne une pâle teinte violette. En Lordaeron, on le servait à la cour, du moins c'est ce qu'on disait en cuisine, comme les cuisines disent des choses sur la cour. Je n'ai jamais vu un roi en boire. Je ne suis pas sûre d'avoir jamais vu un roi. Chauffez le lait doucement et ne le faites jamais bouillir, sinon il forme une peau. Autrefois, une peau sur un thé royal aurait coûté sa place à une cuisinière. Aujourd'hui, elle ne lui coûte rien, et je la retire encore." },
    [1249959] = { "De la vietérule, lavée et tranchée, infusée dans du jus de melon tiède jusqu'à ce que le jus fonce et sente à la fois la terre et l'été. Filtrez avec soin, parce qu'une racine laissée trop longtemps donne au thé le goût du sol. Je ne peux pas le goûter, mais je sens le sol arriver, une note lourde et humide sous la douceur. Retirez la racine avant que cette note n'arrive. Les vivants le remarquent. Ils remarquent toujours ce que je ne peux pas goûter." },
    [1249960] = { "Du nectar sucré et de la pâlerette, un thé pour les blessés, bien que la pâlerette soit ce que mâchent les voleurs pour disparaître. Peut-être les blessés aimeraient-ils disparaître aussi. Chauffez le nectar jusqu'à ce qu'il fume, faites infuser la pâlerette et filtrez avant qu'elle ne devienne amère. Personne ne m'a vendu cette recette. Je l'ai faite d'après une description, pour les patients des apothicaires, qui l'ont bue sans un mot." },
    [1249961] = { "De la soleillette infusée dans du jus de baie lunaire jusqu'à ce que la boisson devienne dorée. Elle sent le foin l'après-midi et un mur tiède au soleil. Il n'y a pas de soleil à Fossoyeuse. Je prépare ce thé quand mes élèves deviennent silencieux et pâles et commencent à oublier la surface, et je le leur mets entre les mains, et il la leur rappelle. Ce n'est pas dans la recette. Cela devrait y être." },
    [1249962] = { "De la sauge-argent des montagnes dans de la rosée matinale, deux choses difficiles à trouver, infusées ensemble en un thé qui sent l'air froid et la pierre. Chauffez doucement la rosée, faites-y infuser la sauge-argent jusqu'à ce que la boisson pâlisse, puis filtrez. Les vivants disent qu'il n'a pas grand goût, ce qui, d'après les apothicaires, aiguise l'esprit. Je crois surtout qu'il leur donne une excuse pour cesser de travailler le temps d'une tasse, et je ne conteste ni l'une ni l'autre croyance." },
    [1249963] = { "De l'eau de source, des épices douces et une petite glande à venin, écrasée et filtrée pour qu'il n'en reste que le piquant. Les apothicaires ont vérifié ma première fournée. Ils l'ont déclarée sans danger pour les vivants, avec une déception que j'ai choisi de ne pas relever. Secouez fort et servez froid. Les vivants disent qu'il mord la langue. Je les crois sur parole, et je les regarde tendre la main vers un second verre." },
    [1249964] = { "Du lait glacé, des épices douces et de l'ichor d'araignée, secoués jusqu'à ce que l'ichor renonce et se mélange. Cela sent un peu l'amande et beaucoup l'araignée. Servez-le aussitôt. S'il attend, il se sépare, et un frappé gélatineux séparé est une chose que personne ne devrait avoir à regarder. Les apothicaires en boivent au pichet en travaillant, ce qui vous apprend quelque chose sur les apothicaires, et je ne dirai pas quoi." },
    [1249965] = { "Je n'essaierai pas de prononcer le nom. Du jus de melon, des épices fortes et un aileron de murloc, secoués jusqu'à ce que l'aileron cède son corps au jus. Cela sent un melon parti au bord de la mer et revenu changé. Les murlocs des Pins argentés en seraient honorés, je crois, ou furieux. Avec les murlocs, c'est difficile à dire, et le bruit est le même. Je le sers aux courageux, et à ceux qui s'ennuient beaucoup." },
    [1249966] = { "Du nectar sucré, des épices fortes et un grand croc réduit en poudre. Le croc rend la boisson crayeuse et épaisse, comme du lait oublié au soleil. Filtrez-la bien, deux fois, parce qu'une boisson qui crisse sous la dent est la seule chose que personne ne pardonne. Je la prépare le soir et la laisse reposer la nuit, seule façon de faire tomber le reste de craie. Les soldats en boivent le matin. Les gardes noirs, qui se battent et ne vivent pas, en boivent par solidarité." },
    [1249967] = { "Du jus de baie lunaire, des épices apaisantes et un petit sac de flammes, percé et pressé dans le verre. Le sac de flammes chauffe, et l'épice adoucit le coup. Secouez et buvez vite. Je ne peux pas vous dire à quel point c'est brûlant. Je peux vous dire que j'ai vu un jour un orc en boire un, puis rester immobile très longtemps, les yeux au plafond, comme si le plafond l'avait insulté." },
    [1249968] = { "De la rosée matinale, beaucoup d'épices apaisantes et une serre cruelle, moulue fin. La serre lui donne une arête sombre et amère que l'épice n'arrive jamais tout à fait à adoucir. Il sent les fleurs écrasées et quelque chose qui aimerait bien vous mordre. Servez-le froid. Les jeunes gardes noirs en boivent par défi. Les vieux en boivent parce qu'ils ont cessé de relever les défis, et ils l'aiment quand même." },
    [1250142] = { "Les vivants aiment la nourriture qui se mange d'une main, et la voici : du cerf haché fin avec des épices fortes, pressé une fois en petites galettes et frit vite. Pressez-les deux fois et le jus file dans la poêle au lieu d'aller à l'invité. J'ai vu des dockers de la tour des zeppelins en avaler une douzaine entre deux arrivées et retourner au travail sans un mot. C'est la critique qui compte." },
    [1250143] = { "Mes élèves fiers de leur couteau héritent de celui-ci : des ailes de busard désossées et battues à plat, roulées autour des épices apaisantes et ficelées. C'est un travail lent et minutieux, et je vérifie chaque rouleau avant qu'il aille au four. Rôtissez doucement et tranchez en rondelles. La spirale à l'intérieur me dit tout du cuisinier qui l'a roulée. Une spirale serrée, une main soigneuse. Une spirale lâche, quelqu'un qui pensait au déjeuner." },
    [1250144] = { "De pauvres fermiers faisaient ce ragoût, de la viande hachée cuite longtemps et doucement. En Lordaeron, c'était du boeuf, quand il y avait du boeuf, ou je crois que c'en était. Ici, c'est de la chauve-souris. Hachez fin les ailes, ajoutez les épices apaisantes et donnez-lui un feu bas pendant une soirée, jusqu'à ce que les tendons s'attendrissent et que la cuisine sente l'épice et quelque chose comme la maison. Mes élèves l'appellent la bouillie de chauve-souris. Moi, je l'appelle le souper." },
    [1250145] = { "Je fais mijoter cette tortue sans jamais la tamiser, parce que c'est un ragoût de ferme et non une bisque de seigneur. Nous en faisions au bord d'une rivière en Lordaeron, j'en suis presque sûre, même si je ne saurais dire laquelle. De la tortue et beaucoup d'épices apaisantes, mijotées jusqu'à ce que la viande se défasse. Laissez-le épais. La texture est tout l'intérêt, et l'odeur, ronde, chaude et lente, est la raison pour laquelle les gens restent au comptoir une fois leur bol fini. J'ai cessé de leur demander de partir. Ils partiront quand le bol sera vide, et pas avant." },
    [1250146] = { "J'ai cherché le poivre dans cette recette sans en trouver, quoi qu'en dise le nom, seulement du flanc de loup rouge et des épices apaisantes, qui font assez bien le travail du poivre. Saisissez le flanc fort, laissez-le reposer pendant que la poêle refroidit, puis reversez son jus par-dessus. L'odeur quand le jus retrouve la viande chaude est tout l'intérêt du plat. Je le sers aux apothicaires quand je veux obtenir quelque chose d'eux, et cela marche." },
    [1250147] = { "Mes élèves se souviennent de celui-ci à son odeur : de la viande de grand ours en fines tranches, en couches avec des épices apaisantes, rôtie lentement jusqu'à ce que les couches se soudent en une seule. Tranchez la viande froide, sinon elle se déchire. Le meilleur, c'est l'odeur quand c'est prêt, sombre et douce, proche du sucre brûlé. Le nom ne me dit rien, ni à aucun de ceux à qui je l'ai demandé. Celui qui l'a nommé faisait le malin. Celui qui l'a cuisiné le premier, non." },
    [1250148] = { "Je frotte le cerf profondément d'épices apaisantes, je le saisis sur un fer très chaud et je le sers aussitôt, tant qu'il fume encore. La vapeur porte l'odeur, et l'odeur est la moitié du repas pour qui peut goûter, et tout le repas pour moi. Ne le faites pas attendre. Un steak qui cesse de fumer a commencé à refroidir, et un steak froid est une promesse que quelqu'un a rompue entre la cuisine et la table." },
    [1250149] = { "Donnez à la viande de tigre ses épices apaisantes, le feu le plus vif que vous puissiez faire et le temps le plus court que vous puissiez supporter. Le nom est celui d'un chasseur. La méthode est celle d'un cuisinier. Frappez vite, puis laissez reposer longtemps, et c'est au repos que tout le monde échoue, parce que l'odeur est merveilleuse et que la fourchette est juste là. Je fais asseoir mes élèves sur leurs mains, et je ne plaisante pas. J'ai appris la méthode d'un chasseur qui ne savait pas attendre non plus." },
    [1250150] = { "J'ai lu cette recette sans qu'on me l'ait jamais vendue, ce qui me la rend suspecte. Les côtelettes cuisent à feu bas jusqu'à ce que la viande lâche l'os, puis sur une flamme féroce pour fixer une épaisse croûte d'épices fortes. La fumée seule m'a fait pleurer, et personne de ceux que j'ai nourris n'a demandé plus d'épices. La croûte doit se briser comme du sucre brûlé sous le couteau. Si elle plie, les côtelettes retournent sur la flamme." },
    [1250151] = { "Mes élèves apprennent à garder le feu bas pour celui-ci, le morceau le plus dur de l'animal le plus dur. Frottez la poitrine d'épices fortes et laissez-la cuire une journée entière, jusqu'à ce qu'elle cède sous la fourchette comme du pain mouillé. On ne peut pas la brusquer. On peut seulement la regarder, et la sentir passer du fer cru à la fumée, puis à quelque chose de riche et de sombre. Quand elle sent un soir d'hiver, elle est prête." },
    [1250152] = { "Les gardes noirs adorent celui-ci parce qu'il se garde. Le raptor cuit presque une journée sur le feu le plus bas que je puisse tenir, avec beaucoup d'épices apaisantes, jusqu'à se défaire au contact d'une fourchette. Effilochez-le à deux fourchettes, jamais au couteau. Il se mange dans un bol en marchant, ce qui leur convient. Il se dit préhistorique. Les manières de certains de mes élèves le sont aussi." },
    [1250153] = { "Je roule de fines tranches de raptor autour des épices fortes et je les ficelle. Les rouleaux cuisent de l'extérieur vers l'intérieur, alors gardez le dernier tour fin. Dorez-les sur toutes les faces, puis baissez le feu et laissez-les. Quand la ficelle fonce et sent le foin brûlé, coupez-la avant que quelqu'un la voie. Un invité pardonne beaucoup de choses, mais pas la ficelle. C'est un invité qui me l'a appris." },
    [1250154] = { "C'est le seul plat où je romps ma propre règle, l'épice avant le feu, pour assaisonner aussi à la fin, parce que le raptor est maigre et que la première couche s'en va à la cuisson. J'ai appris à sentir le moment entre les deux. Quand les tranches cessent de siffler et se mettent à cliqueter, comme une poêle qui refroidit, retirez-les et assaisonnez-les de nouveau tant qu'elles sont assez chaudes pour boire l'épice. Mes élèves oublient toujours la seconde couche. Le plat les dénonce. Il sent la moitié d'une recette." },
    [1250155] = { "Mes élèves redoutent celui-ci. Les oeufs géants et les épices fortes doivent être remués lentement jusqu'à se rassembler en grumeaux tendres, ce qui demande une main sûre. Tout du long, cela sent quelque chose de riche et de chaud, alors qu'il n'y a dans la poêle que l'oeuf et l'épice. Quand l'odeur s'aiguise, arrêtez. Les oeufs sont sur le point d'aller trop loin. J'en sers aux gardes noirs après la garde de nuit, et ils les mangent debout au comptoir, encore en armure." },
    [1250156] = { "Un oeuf de raptor est gros comme mes deux poings, et quand on le casse, il sent un peu le marais où sa mère a marché. L'épice est là pour répondre à cette odeur, et il en faut beaucoup pour lui répondre. Battez l'oeuf, assaisonnez-le et cuisez-le en petits disques sur une pierre chaude. Les disques gonflent quand ils sont cuits. Mes élèves les mangent avant que j'aie pu les compter, ce qui me dit que la recette fonctionne." },
    [1250157] = { "Un oeuf et beaucoup d'épices douces, plus que de raison, d'une recette trouvée dans le nid d'un condor des Carmines. Je l'ai faite telle qu'elle est écrite. Elle sent le matin et un marché aux épices. Battez l'oeuf jusqu'à n'avoir qu'une couleur, versez-le dans une poêle chaude et ramenez les bords à mesure qu'ils prennent. Pliez-la tant qu'elle est tendre. Les vivants qui la mangent disent qu'elle les réveille. Les gardes noirs la mangent pour se rappeler ce qu'étaient les matins." },
    [1250158] = { "Il n'y a pas de pâtes dedans, quoi que promette le nom. Il y a de la chair de palourde piquante, taillée en longs rubans et enrobée d'épices apaisantes. Cuisez-la un instant dans une poêle chaude et servez aussitôt, tout emmêlée. Cela se mange comme des pâtes et sent la mer. Je ne sais pas qui l'a inventée. J'imagine un cuisinier qui n'avait pas de farine et beaucoup de palourdes, et qui ne s'en est pas plaint." },
    [1252566] = { "Un petit poisson vif au nom ridicule. La recette apparaît dans les Carmines, dans les sacs de créatures qui ne cuisinent pas, ce qui veut dire que quelqu'un qui cuisinait l'a perdue là-bas. Une pincée d'épices douces, une poêle chaude, un instant. L'odeur est douce et brève, comme un fruit. Je le prépare quand les équipages des zeppelins amènent leurs enfants en bas, parce que le nom les fait rire, et le rire n'est pas assez fréquent par ici." },
    [1255241] = { "Une fleur gangrenée, purifiée par les druides pour qu'elle ne fasse plus ce que font ces fleurs-là. Je garde mes distances quand même, par habitude. La viande de cerf et un oeuf géant donnent au ragoût sa force, l'oeuf battu à la fin pour que le bouillon devienne soyeux. Il sent les choses vertes et le bouillon chaud et, faiblement, quelque chose de brûlé qui n'est plus là. Je le prépare pour ceux qui reviennent de Gangrebois avec l'air d'avoir ramené la forêt avec eux." },
    [1262978] = { "Macaron est le murloc qui cuisine pour les Défias dans les Mortemines, et celui qui lui a pris cette recette ne l'a pas demandée poliment. Deux portions de viande mystère, une de kodo épais et des épices apaisantes, rôties lentement ensemble jusqu'à ce que le kodo s'attendrisse et que le mystère s'épaississe. Je sens ce qu'était la viande mystère. Dans la cuisine de Macaron, j'aurais préféré ne pas le savoir. Un festin se partage, alors dressez-le sur un seul grand plat et laissez chacun se servir. Mes gardes noirs le font en silence, avec soin, chacun en laissant un peu pour le suivant, ce que les Défias n'ont jamais fait. L'odeur remplit la salle et fait descendre les vivants de la ville au-dessus, et j'ai cessé de les renvoyer. Le festin d'un murloc criminel, dans la cuisine d'une morte, mangé par quiconque a faim. Je crois que Macaron approuverait. Je crois qu'il voudrait récupérer sa louche." },
    [1263067] = { "De la farine, de l'eau de source et des épices apaisantes : voilà toute la recette d'un four en fer. Je crois que la pâte est travaillée dans le four neuf et cuite dure, pour le culotter, comme on culotte une poêle neuve. Je ne l'ai jamais vue en vente. Un marchand gobelin me l'a décrite, persuadé qu'il m'impressionnerait. Il y est parvenu. Je ne le lui ai pas dit. Les gobelins sont insupportables quand ils savent qu'ils ont fait impression, et ils le mettent sur la note." },
    [1270632] = { "De la farine et rien d'autre, cuite en petits biscuits pour les créatures qui suivent les aventuriers partout. J'en fais pour les rats de Fossoyeuse qui ont gagné mon respect, c'est-à-dire trois. Travaillez la farine légèrement et cuisez les biscuits pâles. Ils sentent le pain chaud et rien de plus, et c'est tant mieux, parce qu'un animal qui prend goût aux épices ne vous laissera plus jamais tranquille." },
    [1270633] = { "Des oeufs et un peu de farine, les blancs montés jusqu'à se tenir, incorporés, et cuits sans jamais ouvrir la porte. On ne voit pas un soufflé monter depuis l'extérieur du four, mais on le sent : l'odeur passe de l'oeuf mouillé au pain chaud au moment où il culmine. Sortez-le alors, et portez-le vite. Un soufflé est un souffle retenu. Il n'attendra pas que l'invité ait fini de parler." },
    [1270635] = { "Des pinces de crabe, cassées et vidées, liées avec le moins de farine possible et frites en petites bouchées. La farine est une corde, pas un repas. Mettez-en trop et les bouchées ne sentent que le pain. Mettez-en juste assez et elles sentent la mer et la poêle. La saison des crabes, dit la recette. D'après moi, toutes les saisons sont celles des crabes, si l'on vit assez près de l'eau." },
    [1283400] = { "Le bois d'étoile brûle plus chaud et plus proprement que le bois commun, avec une odeur de résine et de givre. La recette vient des Cavernes des lamentations, où les druides ont mal rêvé, et quelqu'un a décidé qu'un meilleur feu de camp valait le voyage. Empilez-le de la même façon et laissez-le retomber davantage avant de cuisiner, parce qu'un feu plus chaud pardonne moins. Quand les braises blanchissent sur les bords, il est temps de cuisiner." },
    [1291341] = { "Des bûches épaisses, lentes à prendre et lentes à mourir, un feu pour toute une soirée. Disposez-les en carré avec un passage pour l'air et allumez-les par-dessous. Puis attendez. L'odeur change quand il est prêt, de la fumée verte à la fumée sèche, de l'âcre au doux. C'est le feu d'un spécialiste, et la leçon d'un spécialiste : la meilleure chaleur est celle qu'on a attendue. On ne m'a pas vendu cette recette. Je le bâtis d'après ce qu'on m'en a dit, et celui qui me l'a dit savait de quoi il parlait." },
    [1294014] = { "Des baies d'Hyjal, réduites lentement avec des épices apaisantes jusqu'à ce qu'une goutte sur une assiette froide se ride quand on la pousse. Le meilleur, c'est l'odeur, et je peux vous le dire avec une certaine autorité : fruit sombre et épice chaude, si sucrée qu'elle en est presque bruyante. Les ours pillent les buissons pour ces baies, dit la recette. Je ferais pareil, si j'étais un ours." },
    [1295805] = { "Un ragoût du rivage : du crabe, des yeux de murloc et des épices fortes. Les yeux épaississent le bouillon, alors ne les enlevez pas pour ménager qui que ce soit. Le crabe entre à la fin, pour rester doux. L'odeur est celle de la mer avant qu'on l'ait rangée, sel, algue et quelque chose d'encore vivant. Mes élèves se pincent le nez la première fois. La deuxième fois, ils demandent un bol." },
    [1295834] = { "Du sanglier rôti sur l'os avec un peu d'épices douces et rien d'autre, comme les cuisines de ferme l'ont toujours fait. La recette vient des Rives Claires, de quelqu'un qui avait visiblement des gens affamés à nourrir. Rôtissez jusqu'à ce que la graisse crépite et que l'odeur passe de la viande à la noisette. Ne le décorez pas. Un plat simple est une promesse que la viande est bonne, et le cuisinier qui ajoute des choses avoue qu'elle ne l'était pas." },
    [1319313] = { "Un poisson en armure. Les plaques s'enlèvent avec un couteau lourd et beaucoup de patience, et la chair dessous est ferme et pâle, comme celle d'un homard. Des épices apaisantes, une chaleur modérée, et aucune hâte. Les choses en armure prennent leur temps. Les gardes noirs dans leurs plaques diraient la même chose. Servez-le dans ses propres plaques, lavées. Cela fait sourire les gens. Mes élèves apprennent plus de patience avec ce poisson qu'ils n'en apprendront jamais de moi." },
  },
}
